// Network simplex for dense OT, Bonneel-style, with selectable pivot rule.
// pivot_rule: 0 = first improving (row-major), 1 = Dantzig most-negative reduced cost
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <cstring>
#include <limits>

static constexpr int NODE_IN_TREE = 0;
static constexpr int NODE_OUT = 1; // not used much

struct Result {
    int iters;
    int status; // 1 ok
};

// Graph nodes: sources 0..n-1, targets n..n+m-1, root n+m
// We'll use parent, depth, edge_to_parent (the other endpoint), flow on tree edge toward parent? 
// Standard: each non-root node has a parent. The tree edge is (node, parent) if one is source and one is target.
// Flow is stored in a dense matrix G[i*m+j] for supply edges, plus artificial edges flow separately.

template<int PIVOT>
Result solve_ns(const double* a, const double* b, const double* M,
                int n, int m, double* G, int max_iter) {
    const int N = n + m;          // real nodes
    const int root = N;           // artificial root
    const int nnodes = N + 1;

    std::vector<int> parent(nnodes);
    std::vector<int> depth(nnodes);
    std::vector<double> potential(nnodes, 0.0);
    std::vector<double> flow_to_parent(nnodes, 0.0); // flow on edge node->parent (mass from source side interpretation varies)
    // orientation: we store signed flow such that positive means the edge is oriented node -> parent in the residual? 
    // Easier approach: store the basic flow in G for real edges, and art_flow[node] for artificial edges to root.
    // When we need flow on tree edge, look it up.

    std::vector<double> art_flow(N, 0.0); // flow on artificial edge between node and root. Positive = supply sent to root from source, or demand taken from root to target.
    std::vector<char> is_art(N, 0); // whether parent edge is artificial (parent==root)

    std::memset(G, 0, sizeof(double) * n * m);

    // Initialize: connect all sources and targets to root.
    // potential: root = 0. For source i, artificial edge cost 0, so u_i = 0. For target j, cost 0, v_j = 0.
    // Reduced cost of real edge i->j is M[i,j] - u_i - v_j = M[i,j].
    // Flow: source i sends a[i] to root; root sends b[j] to target j.
    parent[root] = -1;
    depth[root] = 0;
    potential[root] = 0.0;
    for (int i = 0; i < n; ++i) {
        parent[i] = root;
        depth[i] = 1;
        potential[i] = 0.0; // cost of artificial is 0, oriented?
        art_flow[i] = a[i];
        is_art[i] = 1;
    }
    for (int j = 0; j < m; ++j) {
        int node = n + j;
        parent[node] = root;
        depth[node] = 1;
        potential[node] = 0.0;
        art_flow[node] = b[j];
        is_art[node] = 1;
    }

    auto set_potential_subtree = [&](int start, double pot) {
        // BFS/stack over children
        std::vector<int> stack;
        stack.push_back(start);
        potential[start] = pot;
        // build children lists on the fly each time? expensive. We'll scan all nodes.
        // For correctness first, scan.
        // Actually we need children. Let's maintain children adjacency.
    };

    // Maintain children lists
    std::vector<std::vector<int>> children(nnodes);
    for (int i = 0; i < N; ++i) children[root].push_back(i);

    auto recompute_potentials_from = [&](int node) {
        // potential already set for node; update descendants
        std::vector<int> stack;
        stack.push_back(node);
        while (!stack.empty()) {
            int u = stack.back(); stack.pop_back();
            for (int c : children[u]) {
                // edge between u and c. If artificial, cost 0.
                // potential consistency: for a real basic edge (i,j), u_i + v_j = M_ij
                // We store potential[source]=u, potential[target]=v
                if (c < n && u >= n && u < N) {
                    // c source, u target: M[c, u-n] = u_c + v_u
                    potential[c] = M[c * m + (u - n)] - potential[u];
                } else if (u < n && c >= n && c < N) {
                    // u source, c target
                    potential[c] = M[u * m + (c - n)] - potential[u];
                } else {
                    // artificial, cost 0: potentials equal? 
                    // Artificial edges have cost 0. Depending on orientation in dual.
                    // We defined artificial cost 0 meaning u_i = pot_root for sources (u_i + 0 = 0? )
                    // Let's define: artificial source-root has reduced-cost equality: potential[source] = potential[root]
                    // artificial target-root: potential[target] = potential[root]
                    potential[c] = potential[u];
                }
                stack.push_back(c);
            }
        }
    };

    auto flow_on_edge = [&](int src_node, int tgt_node) -> double {
        // return current basic flow. One of them may be root.
        if (src_node == root || tgt_node == root) {
            int node = src_node == root ? tgt_node : src_node;
            return art_flow[node];
        }
        int i, j;
        if (src_node < n) { i = src_node; j = tgt_node - n; }
        else { i = tgt_node; j = src_node - n; }
        return G[i * m + j];
    };

    auto set_flow_on_edge = [&](int src_node, int tgt_node, double f) {
        if (src_node == root || tgt_node == root) {
            int node = src_node == root ? tgt_node : src_node;
            art_flow[node] = f;
            return;
        }
        int i, j;
        if (src_node < n) { i = src_node; j = tgt_node - n; }
        else { i = tgt_node; j = src_node - n; }
        G[i * m + j] = f;
    };

    // Find cycle and augment. entering edge (i, jn) where jn is target node index n+j
    auto pivot = [&](int enter_i, int enter_j) -> bool {
        int si = enter_i;
        int tj = n + enter_j;
        // Find path from si to root and tj to root, then LCA
        // record paths
        std::vector<int> path_s, path_t;
        for (int x = si; x != -1; x = parent[x]) path_s.push_back(x);
        for (int x = tj; x != -1; x = parent[x]) path_t.push_back(x);
        // LCA
        int ia = (int)path_s.size() - 1, ib = (int)path_t.size() - 1;
        while (ia >= 0 && ib >= 0 && path_s[ia] == path_t[ib]) { --ia; --ib; }
        // LCA is path_s[ia+1]
        int lca = path_s[ia + 1];
        // cycle edges: entering + path si up to lca + path tj up to lca
        // We need the leaving edge: minimum residual capacity in the direction we augment.
        // Augmentation: we add flow on entering edge i->j (source to target), which means
        // we send mass from si to tj. To balance, along path si->lca we need to adjust, and tj->lca.
        //
        // Orientation convention:
        // A tree edge between source p and target q carries flow G[p,q] from source to target.
        // An artificial edge on source carries flow art_flow = mass from source to root (like source exporting to root).
        // An artificial edge on target carries flow art_flow = mass from root to target (root supplying target).
        //
        // When we add delta on entering (si -> tj):
        // Walk from si up to lca. For each tree edge, determine if we are going "up" and how flow changes.
        // This is the tricky part. Let's use signed residual based on node types.
        //
        // Standard network: supply nodes have supply a_i, demand nodes have demand b_j, root balances.
        // Edges source->target capacity inf, cost M. Artificial source->root cost 0 cap inf, root->target cost 0 cap inf.
        // Flow on source->target is nonnegative.
        //
        // Adding delta on si->tj increases flow out of si and into tj.
        // To restore, we need to decrease net outflow of si by delta along the tree path, etc.
        //
        // Let's compute the direction of augmentation on each tree edge by seeing whether the edge is traversed
        // from source-side to target-side or reverse when going along the cycle.
        //
        // Cycle direction: si --enter--> tj --up path_t to lca-- then --down reverse path_s to si--.
        // For residual:
        // - entering edge can take +inf
        // - for each tree edge, if we traverse it in the forward direction (source->target or source->root or root->target), residual is inf - flow = inf
        // - if we traverse it backward, residual is current flow
        //
        // Leaving edge is the backward-traversed tree edge with smallest flow. If several, pick one (Bland: the one ...).
        // Bonneel uses a specific rule. For now any min is fine for feasibility; basis choice affects which optimal vertex.
        //
        // Determine traversal direction for edges on path_t (from tj up to lca): we traverse child -> parent.
        // For edges on path_s (from lca down to si, i.e. we traverse parent -> child when closing cycle, which is reverse of child->parent stored): 
        // Wait let's be careful.
        // Cycle: start at si, go via entering to tj, then from tj climb to lca (child to parent along path_t), then from lca descend to si (parent to child along reverse path_s).
        //
        // path_s: [si, parent, ..., lca] so climbing si to lca is child->parent.
        // But in the cycle after reaching lca we go back down to si, so we traverse path_s edges in parent->child direction.
        //
        // path_t: [tj, parent, ..., lca], cycle traverses these child->parent.

        struct EdgeTrav {
            int child; // the non-parent endpoint? store both endpoints and whether backward
            int parent_node;
            bool backward; // traversed against forward direction
            double flow;
        };
        std::vector<EdgeTrav> cand; // candidate leaving edges (backward ones)

        auto consider = [&](int child, int par, bool traversing_child_to_parent) {
            // Determine forward direction of this tree edge and whether this traversal is backward.
            bool backward = false;
            double flow = 0;
            if (par == root) {
                // artificial
                if (child < n) {
                    // forward: source -> root. child_to_parent is forward.
                    backward = !traversing_child_to_parent;
                    flow = art_flow[child];
                } else {
                    // forward: root -> target. child_to_parent is backward.
                    backward = traversing_child_to_parent;
                    flow = art_flow[child];
                }
            } else {
                // real edge between source and target
                // forward: source -> target
                int src = child < n ? child : par;
                // traversing from child to par
                bool child_is_source = child < n;
                // forward traversal would be source -> target
                bool traversing_forward = child_is_source; // child is source and we go child->par means source->target
                // wait if par is source and child is target, traversing child->par is target->source = backward
                backward = !traversing_forward;
                int i = child < n ? child : par;
                int j = (child < n ? par : child) - n;
                flow = G[i * m + j];
                (void)src;
            }
            if (backward) {
                cand.push_back({child, par, true, flow});
            }
        };

        // path_t edges traversed child->parent, from tj up to but not including lca
        for (int k = 0; k <= ib; ++k) {
            int child = path_t[k];
            int par = path_t[k + 1];
            consider(child, par, true);
        }
        // path_s edges traversed parent->child (reverse), from lca down to si
        // path_s[0]=si ... path_s[ia]=node just below lca, path_s[ia+1]=lca
        for (int k = ia; k >= 0; --k) {
            int child = path_s[k];
            int par = path_s[k + 1];
            // traversing par -> child, so NOT child_to_parent
            consider(child, par, false);
        }

        // min flow among backward edges
        double delta = std::numeric_limits<double>::infinity();
        int leave_idx = -1;
        for (int k = 0; k < (int)cand.size(); ++k) {
            if (cand[k].flow < delta - 1e-15) {
                delta = cand[k].flow;
                leave_idx = k;
            } else if (std::abs(cand[k].flow - delta) <= 1e-15) {
                // tie break: keep first (closer to tj side, since path_t pushed first)
            }
        }
        if (leave_idx < 0) {
            // unbounded? shouldn't happen
            delta = 0;
        }
        if (!(delta > 0) && delta != 0) {
            // nan
        }
        // If delta is inf, no backward edge — shouldn't happen with artificial edges present initially.
        if (!std::isfinite(delta)) delta = 0;

        // Apply augmentation of +delta on forward direction around the cycle.
        // entering edge: +delta
        G[enter_i * m + enter_j] += delta;

        auto apply = [&](int child, int par, bool traversing_child_to_parent, double delta) {
            // add delta in the direction of traversal? No: we add delta in cycle direction.
            // Cycle direction on path_t is child->parent, on path_s is parent->child.
            // Forward flow increases if cycle traversal is forward, decreases if backward.
            if (par == root) {
                if (child < n) {
                    // forward source->root. cycle child->parent is forward: flow += delta if traversing c2p
                    if (traversing_child_to_parent) art_flow[child] += delta;
                    else art_flow[child] -= delta;
                } else {
                    // forward root->target. cycle child->parent is backward: flow -= delta if traversing c2p
                    if (traversing_child_to_parent) art_flow[child] -= delta;
                    else art_flow[child] += delta;
                }
            } else {
                int i = child < n ? child : par;
                int j = (child < n ? par : child) - n;
                bool child_is_source = child < n;
                bool traversing_forward = child_is_source; // c2p and child source => forward
                if (traversing_child_to_parent) {
                    if (traversing_forward) G[i * m + j] += delta;
                    else G[i * m + j] -= delta;
                } else {
                    if (traversing_forward) G[i * m + j] -= delta;
                    else G[i * m + j] += delta;
                }
            }
        };

        for (int k = 0; k <= ib; ++k) apply(path_t[k], path_t[k + 1], true, delta);
        for (int k = ia; k >= 0; --k) apply(path_s[k], path_s[k + 1], false, delta);

        // Remove leaving edge from tree, add entering edge.
        // Leaving edge endpoints: cand[leave_idx].child and .parent_node, where child->parent is the tree orientation.
        if (leave_idx < 0) return false;
        int Lchild = cand[leave_idx].child;
        int Lpar = cand[leave_idx].parent_node;

        // Zero out leaving edge flow (numerical)
        set_flow_on_edge(Lchild, Lpar, 0.0);

        // Update tree: the leaving edge splits tree. The subtree that contains the side of the entering edge
        // needs to be reattached via the entering edge.
        // Standard approach: identify which side of leaving edge is not connected to root after removal,
        // then reroot that subtree so that the entering-edge endpoint in that subtree becomes the new root of subtree,
        // and attach it to the other entering endpoint.
        //
        // After removal of Lchild-Lpar, the component not containing the original root is the subtree of Lchild
        // (since Lpar is closer to root... wait is it? parent pointers point toward root, so Lchild's subtree is the one detached. Yes if parent links point to root.
        // parent[Lchild]==Lpar, so removing edge detaches subtree of Lchild. Good.

        // We need to reroot the detached subtree so that `attach` (the entering endpoint inside the subtree) becomes the top,
        // then set its parent to the other entering endpoint.
        int in_sub = -1, out_sub = -1;
        // which of si, tj is in subtree of Lchild?
        auto in_subtree = [&](int node, int subroot) {
            for (int x = node; x != -1; x = parent[x]) if (x == subroot) return true;
            return false;
        };
        // Careful: we haven't removed parent link yet, so in_subtree works.
        bool si_in = in_subtree(si, Lchild);
        bool tj_in = in_subtree(tj, Lchild);
        // Exactly one of the entering endpoints should be in the detached subtree (the leaving edge is on the cycle).
        if (si_in && !tj_in) { in_sub = si; out_sub = tj; }
        else if (tj_in && !si_in) { in_sub = tj; out_sub = si; }
        else {
            // degenerate, shouldn't happen
            return false;
        }

        // Reroot subtree of Lchild so in_sub becomes root of that subtree.
        // Collect path from in_sub up to Lchild and reverse parent pointers.
        std::vector<int> rpath;
        for (int x = in_sub; x != Lpar; x = parent[x]) rpath.push_back(x);
        // rpath[0]=in_sub, rpath.back()=Lchild
        // Reverse: for each consecutive pair, flip parent
        // Also need to update children lists and flows? Flows already updated globally in G/art_flow, independent of orientation. Good.
        // Potentials will be recomputed.
        for (int k = (int)rpath.size() - 1; k >= 1; --k) {
            int node = rpath[k];     // currently parent of rpath[k-1]
            int newpar = rpath[k - 1];
            // remove node from its current parent's children
            int oldpar = parent[node];
            auto& ch = children[oldpar];
            ch.erase(std::find(ch.begin(), ch.end(), node));
            parent[node] = newpar;
            children[newpar].push_back(node);
        }
        // detach Lchild from Lpar if not already moved (if Lchild==in_sub, rpath size 1, loop didn't run, still attached)
        if (parent[Lchild] == Lpar) {
            auto& ch = children[Lpar];
            ch.erase(std::find(ch.begin(), ch.end(), Lchild));
            // parent will be overwritten below if Lchild==in_sub
        }
        // Now in_sub should be the root of the detached subtree (parent pointer still old if size==1).
        // Attach in_sub to out_sub.
        if (parent[in_sub] != -1 && parent[in_sub] != out_sub) {
            int old = parent[in_sub];
            if (old != -1 && old != out_sub) {
                auto& ch = children[old];
                auto it = std::find(ch.begin(), ch.end(), in_sub);
                if (it != ch.end()) ch.erase(it);
            }
        }
        parent[in_sub] = out_sub;
        children[out_sub].push_back(in_sub);

        // Update depths in subtree of in_sub
        {
            std::vector<int> stack = {in_sub};
            depth[in_sub] = depth[out_sub] + 1;
            while (!stack.empty()) {
                int u = stack.back(); stack.pop_back();
                for (int c : children[u]) {
                    depth[c] = depth[u] + 1;
                    stack.push_back(c);
                }
            }
        }

        // Update potentials in subtree of in_sub based on new parent edge
        {
            // set potential of in_sub from parent edge, then descendants
            int node = in_sub;
            int par = out_sub;
            auto pot_from_parent = [&](int c, int u) {
                if (u == root || c == root) {
                    return potential[u]; // artificial cost 0 => equal potentials
                }
                if (c < n && u >= n && u < N) {
                    return M[c * m + (u - n)] - potential[u];
                } else if (u < n && c >= n && c < N) {
                    return M[u * m + (c - n)] - potential[u];
                } else if (c < n && u < n) {
                    return potential[u];
                } else {
                    return potential[u];
                }
            };
            potential[node] = pot_from_parent(node, par);
            std::vector<int> stack = {node};
            while (!stack.empty()) {
                int u = stack.back(); stack.pop_back();
                for (int c : children[u]) {
                    potential[c] = pot_from_parent(c, u);
                    stack.push_back(c);
                }
            }
        }
        return true;
    };

    int iters = 0;
    for (; iters < max_iter; ++iters) {
        // find entering edge
        int bi = -1, bj = -1;
        double best = 0.0;
        if constexpr (PIVOT == 0) {
            // first negative reduced cost, row-major, threshold
            for (int i = 0; i < n && bi < 0; ++i) {
                const double* row = M + i * (int64_t)m;
                double ui = potential[i];
                for (int j = 0; j < m; ++j) {
                    double rc = row[j] - ui - potential[n + j];
                    if (rc < -1e-12) { bi = i; bj = j; break; }
                }
            }
        } else {
            for (int i = 0; i < n; ++i) {
                const double* row = M + i * (int64_t)m;
                double ui = potential[i];
                for (int j = 0; j < m; ++j) {
                    double rc = row[j] - ui - potential[n + j];
                    if (rc < best) { best = rc; bi = i; bj = j; }
                }
            }
        }
        if (bi < 0) break; // optimal
        if (!pivot(bi, bj)) break;
    }
    Result r;
    r.iters = iters;
    r.status = 1;
    return r;
}

// export C
extern "C" {
int network_simplex(const double* a, const double* b, const double* M,
                    int n, int m, double* G, int max_iter, int pivot) {
    if (pivot == 0) {
        return solve_ns<0>(a, b, M, n, m, G, max_iter).iters;
    } else {
        return solve_ns<1>(a, b, M, n, m, G, max_iter).iters;
    }
}
}
