// Network simplex for dense OT.
// pivot: 0 = first improving (row-major), 1 = most-negative reduced cost
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <cstring>
#include <limits>

template<int PIVOT>
int solve_ns(const double* a, const double* b, const double* M,
             int n, int m, double* G, int max_iter) {
    const int N = n + m;
    const int root = N;
    const int nnodes = N + 1;

    std::vector<int> parent(nnodes);
    std::vector<int> depth(nnodes);
    std::vector<double> potential(nnodes, 0.0);
    std::vector<double> art_flow(N, 0.0);
    std::vector<std::vector<int>> children(nnodes);

    std::memset(G, 0, sizeof(double) * (size_t)n * (size_t)m);

    parent[root] = -1;
    depth[root] = 0;
    potential[root] = 0.0;
    for (int i = 0; i < n; ++i) {
        parent[i] = root;
        depth[i] = 1;
        potential[i] = 0.0;
        art_flow[i] = a[i];
        children[root].push_back(i);
    }
    for (int j = 0; j < m; ++j) {
        int node = n + j;
        parent[node] = root;
        depth[node] = 1;
        potential[node] = 0.0;
        art_flow[node] = b[j];
        children[root].push_back(node);
    }

    auto set_flow_zero = [&](int u, int v) {
        if (u == root || v == root) {
            int node = u == root ? v : u;
            art_flow[node] = 0.0;
            return;
        }
        int i = u < n ? u : v;
        int j = (u < n ? v : u) - n;
        G[(size_t)i * m + j] = 0.0;
    };

    auto pivot = [&](int enter_i, int enter_j) -> bool {
        int si = enter_i;
        int tj = n + enter_j;

        std::vector<int> path_s, path_t;
        path_s.reserve(64);
        path_t.reserve(64);
        for (int x = si; x != -1; x = parent[x]) path_s.push_back(x);
        for (int x = tj; x != -1; x = parent[x]) path_t.push_back(x);

        int ia = (int)path_s.size() - 1;
        int ib = (int)path_t.size() - 1;
        while (ia >= 0 && ib >= 0 && path_s[ia] == path_t[ib]) { --ia; --ib; }

        struct Cand { int child, par; double flow; };
        std::vector<Cand> cand;
        cand.reserve(ia + ib + 4);

        auto consider = [&](int child, int par, bool child_to_parent) {
            bool backward = false;
            double flow = 0.0;
            if (par == root) {
                if (child < n) {
                    backward = !child_to_parent;
                    flow = art_flow[child];
                } else {
                    backward = child_to_parent;
                    flow = art_flow[child];
                }
            } else {
                bool child_is_source = child < n;
                backward = child_to_parent ? !child_is_source : child_is_source;
                int i = child < n ? child : par;
                int j = (child < n ? par : child) - n;
                flow = G[(size_t)i * m + j];
            }
            if (backward) cand.push_back({child, par, flow});
        };

        for (int k = 0; k <= ib; ++k) consider(path_t[k], path_t[k + 1], true);
        for (int k = ia; k >= 0; --k) consider(path_s[k], path_s[k + 1], false);

        double delta = std::numeric_limits<double>::infinity();
        int leave_idx = -1;
        for (int k = 0; k < (int)cand.size(); ++k) {
            if (cand[k].flow < delta) {
                delta = cand[k].flow;
                leave_idx = k;
            }
        }
        if (leave_idx < 0 || !std::isfinite(delta)) return false;
        if (delta < 0) delta = 0;

        G[(size_t)enter_i * m + enter_j] += delta;

