        int Lpar = cand[leave_idx].parent_node_dummy = 0;
        Lpar = cand[leave_idx].par;
        set_flow_zero(Lchild, Lpar);

        auto in_subtree = [&](int node, int subroot) {
            for (int x = node; x != -1; x = parent[x]) if (x == subroot) return true;
            return false;
        };
