            parent[node] = newpar;
            children[newpar].push_back(node);
        }
        if (parent[Lchild] == Lpar) {
            auto& ch = children[Lpar];
            auto it = std::find(ch.begin(), ch.end(), Lchild);
            if (it != ch.end()) ch.erase(it);
        }
        {
            int old = parent[in_sub];
            if (old != -1 && old != out_sub) {
