            stack.push_back(in_sub);
            depth[in_sub] = depth[out_sub] + 1;
            while (!stack.empty()) {
                int u = stack.back(); stack.pop_back();
                for (int c : children[u]) {
                    depth[c] = depth[u] + 1;
                    stack.push_back(c);
                }
            }
        }

        auto pot_from_parent = [&](int c, int u) -> double {
            if (u == root || c == root) return potential[u];
            if (c < n && u >= n && u < N) {
                return M[(size_t)c * m + (u - n)] - potential[u];
            } else if (u < n && c >= n && c < N) {
                return M[(size_t)u * m + (c - n)] - potential[u];
            }
            return potential[u];
        };
        potential[in_sub] = pot_from_parent(in_sub, out_sub);
        {
            std::vector<int> stack;
            stack.push_back(in_sub);
            while (!stack.empty()) {
                int u = stack.back(); stack.pop_back();
                for (int c : children[u]) {
                    potential[c] = pot_from_parent(c, u);
                    stack.push_back(c);
                }
            }
        }
        return true;
    };

    int iters = 0;
    const double tol = 1e-12;
    for (; iters < max_iter; ++iters) {
        int bi = -1, bj = -1;
        if constexpr (PIVOT == 0) {
            for (int i = 0; i < n && bi < 0; ++i) {
                const double* row = M + (size_t)i * m;
                double ui = potential[i];
                for (int j = 0; j < m; ++j) {
                    double rc = row[j] - ui - potential[n + j];
                    if (rc < -tol) { bi = i; bj = j; break; }
                }
            }
        } else {
            double best = -tol;
            for (int i = 0; i < n; ++i) {
                const double* row = M + (size_t)i * m;
                double ui = potential[i];
                for (int j = 0; j < m; ++j) {
                    double rc = row[j] - ui - potential[n + j];
                    if (rc < best) { best = rc; bi = i; bj = j; }
                }
            }
        }
        if (bi < 0) break;
        if (!pivot(bi, bj)) break;
    }
    return iters;
}

extern "C" {
int network_simplex(const double* a, const double* b, const double* M,
                    int n, int m, double* G, int max_iter, int pivot) {
    if (pivot == 0) return solve_ns<0>(a, b, M, n, m, G, max_iter);
    return solve_ns<1>(a, b, M, n, m, G, max_iter);
}
}
