// Faster network simplex for dense square OT with uniform-ish marginals.
// Candidate-list (partial pricing) + block pivot + array-based spanning tree.
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <numeric>

struct Solver {
    int n, m, N, root, nnodes;
    const double* a;
    const double* b;
    const double* M;
    double* G;
    double Cbig;
    double tol;

    std::vector<int> parent, depth, preorder, size_sub;
    std::vector<int> child_head, child_next; // linked children
    std::vector<double> potential, art_flow;
    std::vector<int> thread_idx; // preorder index

    // candidate list
    std::vector<int> cand_i, cand_j;
    int cand_cap;

    explicit Solver(const double* a_, const double* b_, const double* M_, double* G_, int n_, int m_)
        : n(n_), m(m_), N(n_ + m_), root(n_ + m_), nnodes(n_ + m_ + 1),
          a(a_), b(b_), M(M_), G(G_), Cbig(0), tol(1e-12) {
        for (size_t k = 0, K = (size_t)n * m; k < K; ++k) if (M[k] > Cbig) Cbig = M[k];
        Cbig += 1.0;
        parent.assign(nnodes, -1);
        depth.assign(nnodes, 0);
        preorder.assign(nnodes, 0);
        size_sub.assign(nnodes, 1);
        child_head.assign(nnodes, -1);
        child_next.assign(nnodes, -1);
        potential.assign(nnodes, 0.0);
        art_flow.assign(N, 0.0);
        thread_idx.assign(nnodes, 0);
        cand_cap = std::max(64, 4 * std::max(n, m));
        cand_i.reserve(cand_cap);
        cand_j.reserve(cand_cap);
    }

    inline void link_child(int par, int c) {
        child_next[c] = child_head[par];
        child_head[par] = c;
        parent[c] = par;
    }
    inline void unlink_child(int par, int c) {
        int* pp = &child_head[par];
        while (*pp != -1 && *pp != c) pp = &child_next[*pp];
        if (*pp == c) *pp = child_next[c];
        child_next[c] = -1;
    }

    void init() {
        std::memset(G, 0, sizeof(double) * (size_t)n * m);
        parent[root] = -1;
        depth[root] = 0;
        potential[root] = 0.0;
        child_head[root] = -1;
        for (int i = 0; i < n; ++i) {
            potential[i] = Cbig;
            art_flow[i] = a[i];
            depth[i] = 1;
            link_child(root, i);
        }
        for (int j = 0; j < m; ++j) {
            int node = n + j;
            potential[node] = Cbig;
            art_flow[node] = b[j];
            depth[node] = 1;
            link_child(root, node);
        }
        refresh_tree_index();
    }

    void refresh_tree_index() {
        // preorder + subtree sizes + thread (next in preorder)
        int timer = 0;
        std::vector<int> stack;
        stack.push_back(root);
        std::vector<int> seen_child(nnodes, -2);
        // iterative DFS
        std::vector<int> dfs;
        dfs.push_back(root);
        std::vector<char> state(nnodes, 0);
        while (!dfs.empty()) {
            int u = dfs.back();
            if (state[u] == 0) {
                state[u] = 1;
                preorder[u] = timer;
                thread_idx[timer] = u;
                timer++;
                // push children
                for (int c = child_head[u]; c != -1; c = child_next[c]) dfs.push_back(c);
            } else {
                dfs.pop_back();
                int sz = 1;
                for (int c = child_head[u]; c != -1; c = child_next[c]) sz += size_sub[c];
                size_sub[u] = sz;
            }
