            if (backward && flow < delta) {
                delta = flow;
                leave_child = child;
                leave_par = par;
            }
        };
        for (int k = 0; k <= ib; ++k) consider(path_t[k], path_t[k + 1], true);
        for (int k = ia; k >= 0; --k) consider(path_s[k], path_s[k + 1], false);
        if (leave_child < 0 || !std::isfinite(delta)) return false;
        if (delta < 0) delta = 0;

        // augment
        G[(size_t)enter_i * m + enter_j] += delta;
