            if (par == root) {
                if (child < n) art_flow[child] += child_to_parent ? delta : -delta;
                else art_flow[child] += child_to_parent ? -delta : delta;
            } else {
                int i = child < n ? child : par;
                int j = (child < n ? par : child) - n;
                bool child_is_source = child < n;
                bool forward = child_to_parent ? child_is_source : !child_is_source;
                G[(size_t)i * m + j] += forward ? delta : -delta;
            }
        };
        for (int k = 0; k <= ib; ++k) apply(path_t[k], path_t[k + 1], true);
        for (int k = ia; k >= 0; --k) apply(path_s[k], path_s[k + 1], false);

        // zero leaving edge
        if (leave_par == root || leave_child == root) {
            int node = leave_par == root ? leave_child : leave_par;
            art_flow[node] = 0.0;
        } else {
            int i = leave_child < n ? leave_child : leave_par;
            int j = (leave_child < n ? leave_par : leave_child) - n;
            G[(size_t)i * m + j] = 0.0;
        }

        // which entering endpoint is in subtree of leave_child
        auto in_sub = [&](int node, int sub) {
            for (int x = node; x != -1; x = parent[x]) if (x == sub) return true;
            return false;
        };
        bool si_in = in_sub(si, leave_child);
        bool tj_in = in_sub(tj, leave_child);
        int in_node, out_node;
        if (si_in && !tj_in) { in_node = si; out_node = tj; }
        else if (tj_in && !si_in) { in_node = tj; out_node = si; }
        else return false;

        // reroot subtree: reverse parent links from in_node up to leave_child
        std::vector<int> rpath;
        rpath.reserve(64);
        for (int x = in_node; x != -1; x = parent[x]) {
            rpath.push_back(x);
            if (x == leave_child) break;
        }
        for (int k = (int)rpath.size() - 1; k >= 1; --k) {
            int node = rpath[k];
            int newpar = rpath[k - 1];
            int oldpar = parent[node];
            unlink_child(oldpar, node);
            link_child(newpar, node);
        }
        if (parent[leave_child] == leave_par) unlink_child(leave_par, leave_child);
        if (parent[in_node] != out_node) {
            int old = parent[in_node];
            if (old != -1) unlink_child(old, in_node);
            link_child(out_node, in_node);
        }

        // update depth + potential in subtree of in_node
        auto pot_from_parent = [&](int c, int u) -> double {
            if (u == root) return Cbig;
