            if (u < n && c >= n && c < N) return M[(size_t)u * m + (c - n)] - potential[u];
            return potential[u];
        };
        potential[in_node] = pot_from_parent(in_node, out_node);
        depth[in_node] = depth[out_node] + 1;
        // DFS stack
        std::vector<int> st;
        st.push_back(in_node);
        while (!st.empty()) {
            int u = st.back(); st.pop_back();
            for (int c = child_head[u]; c != -1; c = child_next[c]) {
