                potential[c] = pot_from_parent(c, u);
                st.push_back(c);
            }
        }
        return true;
    }

    // Sample a candidate list of edges with negative reduced cost. Major pricing scans all,
    // minor pricing samples.
    int price(bool full, int& bi, int& bj) {
        cand_i.clear();
        cand_j.clear();
        bi = -1; bj = -1;
        double best = -tol;
        // stride sampling if not full
        int stride = full ? 1 : std::max(1, n / 32);
        int found = 0;
        for (int i = 0; i < n; i += stride) {
            const double* row = M + (size_t)i * m;
            double ui = potential[i];
            int jstride = full ? 1 : std::max(1, m / 32);
            for (int j = 0; j < m; j += jstride) {
                double rc = row[j] - ui - potential[n + j];
