                }
            }
        }
        return found;
    }

    // pivot the most negative in the candidate list; refresh their reduced costs
    bool pivot_best_candidate() {
        double best = -tol;
        int bi = -1, bj = -1, bidx = -1;
        int C = (int)cand_i.size();
        for (int k = 0; k < C; ++k) {
            int i = cand_i[k], j = cand_j[k];
            double rc = M[(size_t)i * m + j] - potential[i] - potential[n + j];
            if (rc < best) { best = rc; bi = i; bj = j; bidx = k; }
        }
        if (bi < 0) return false;
        // remove from list (swap-pop)
        cand_i[bidx] = cand_i.back(); cand_i.pop_back();
        cand_j[bidx] = cand_j.back(); cand_j.pop_back();
        return pivot(bi, bj);
    }

    int run(int max_iter) {
        init();
        int iters = 0;
        int since_full = 0;
        bool need_full = true;
        while (iters < max_iter) {
            int bi, bj;
            if (cand_i.empty() || since_full > 40) {
                int found = price(need_full || since_full > 40, bi, bj);
                if (found == 0) {
                    if (!need_full) { need_full = true; continue; }
                    break; // optimal
                }
                since_full = 0;
                need_full = false;
                // do the best found immediately
                if (!pivot(bi, bj)) break;
                iters++;
                since_full++;
            } else {
                if (!pivot_best_candidate()) {
                    cand_i.clear();
                    need_full = true;
                    continue;
                }
                iters++;
                since_full++;
            }
        }
        return iters;
    }
};

extern "C" {
int network_simplex(const double* a, const double* b, const double* M,
                    int n, int m, double* G, int max_iter, int /*pivot*/) {
    Solver s(a, b, M, G, n, m);
    return s.run(max_iter);
}
