// Network simplex, optimized:
// - northwest-corner initial basis (no artificial flow left, except one balancing edge if needed)
// - array children
// - partial pricing with a large candidate pool, multiple pivots per pricing
// - no per-pivot heap allocations in the hot path (preallocated buffers)
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>

struct Solver {
    int n, m, N, root, nnodes;
    const double* a;
    const double* b;
    const double* M;
    double* G;
    double tol;

    std::vector<int> parent;
    std::vector<int> depth;
    std::vector<int> head, next; // children linked list
    std::vector<double> pot;
    std::vector<double> art; // artificial flow to root, 0 if not artificial-basic

    // scratch
    std::vector<int> path_s, path_t, rpath, stack;
    std::vector<int> ci, cj;
    int cand_cap;

    Solver(const double* a_, const double* b_, const double* M_, double* G_, int n_, int m_)
        : n(n_), m(m_), N(n_+m_), root(n_+m_), nnodes(n_+m_+1),
          a(a_), b(b_), M(M_), G(G_), tol(1e-11) {
        parent.assign(nnodes, -1);
        depth.assign(nnodes, 0);
        head.assign(nnodes, -1);
        next.assign(nnodes, -1);
        pot.assign(nnodes, 0.0);
        art.assign(N, 0.0);
        path_s.resize(nnodes);
        path_t.resize(nnodes);
        rpath.reserve(nnodes);
        stack.reserve(nnodes);
        cand_cap = std::min(n * m, std::max(4096, 8 * n));
        ci.reserve(cand_cap);
        cj.reserve(cand_cap);
    }

    inline void link(int p, int c) {
        next[c] = head[p];
        head[p] = c;
        parent[c] = p;
    }
    inline void unlink(int p, int c) {
        int* pp = &head[p];
        while (*pp != -1 && *pp != c) pp = &next[*pp];
        if (*pp == c) *pp = next[c];
        next[c] = -1;
    }

    void init_nw() {
        std::memset(G, 0, sizeof(double) * (size_t)n * (size_t)m);
        std::fill(head.begin(), head.end(), -1);
        std::fill(next.begin(), next.end(), -1);
        std::fill(parent.begin(), parent.end(), -1);
        parent[root] = -1;
        pot[root] = 0;
        depth[root] = 0;

        // Northwest corner on real edges. Build a tree: each basic edge links a source and target.
        // Also keep nodes not yet in the tree attached later.
        std::vector<char> in_tree(N, 0);
