        double* bs = new double[m];
        std::memcpy(as, a, sizeof(double)*n);
        std::memcpy(bs, b, sizeof(double)*m);
        int i = 0, j = 0;
        int basics = 0;
        // We'll root the tree at source 0, and attach targets/sources via basic edges.
        // First collect basic edges, then build tree.
        struct E { int i, j; };
        std::vector<E> edges;
        edges.reserve(n + m);
        while (i < n && j < m) {
            double f = as[i] < bs[j] ? as[i] : bs[j];
            if (f > 0 || edges.empty()) {
                G[(size_t)i * m + j] = f;
                edges.push_back({i, j});
                basics++;
            }
            as[i] -= f;
            bs[j] -= f;
            // numerical
            if (as[i] <= 1e-15 * (a[i] + 1)) as[i] = 0;
            if (bs[j] <= 1e-15 * (b[j] + 1)) bs[j] = 0;
            if (as[i] == 0 && i < n - 1) ++i;
            else if (bs[j] == 0 && j < m - 1) ++j;
            else if (as[i] == 0 && bs[j] == 0) {
                // both exhausted: advance one, add degenerate basic to keep tree connected if needed
                if (i < n - 1 && j < m - 1) {
                    // advance i, the next edge will connect
                    ++i;
                } else if (i < n - 1) ++i;
