            if (u < n) {
                for (int j : adj_t[u]) {
                    int node = n + j;
                    if (vis[node]) continue;
                    vis[node] = 1;
                    link(u, node);
                    pot[node] = M[(size_t)u * m + j] - pot[u];
                    depth[node] = depth[u] + 1;
                    q.push_back(node);
                }
            } else {
                int j = u - n;
                for (int i2 : adj_s[j]) {
                    if (vis[i2]) continue;
                    vis[i2] = 1;
                    link(u, i2);
                    pot[i2] = M[(size_t)i2 * m + j] - pot[u];
                    depth[i2] = depth[u] + 1;
                    q.push_back(i2);
                }
            }
        }
        // Attach any unvisited node to root with artificial flow 0, art cost chosen as 0 so pot = 0.
        // This can leave the basis dual-infeasible which pricing fixes. Flow 0 artificial is a degenerate basic edge.
        for (int node = 0; node < N; ++node) {
            if (!vis[node]) {
                link(root, node);
                pot[node] = 0;
                depth[node] = 1;
                art[node] = 0;
                vis[node] = 1;
            }
        }
        // root itself may have children; parent[root] stays -1. depth[root]=0 pot=0.
        // If source 0 was linked as tree root with parent -1, path_to_root stops. Good.
        // But our cycle code uses parent==-1 as stop, and root is a real node index. Source 0 has parent -1, not root.
        // Artificial edges only exist for nodes whose parent is root.
        (void)basics;
    }

    int path_to_root(int x, int* out) const {
        int len = 0;
        while (x != -1) { out[len++] = x; x = parent[x]; }
        return len;
    }

    bool pivot(int enter_i, int enter_j) {
        int si = enter_i;
        int tj = n + enter_j;
        int ls = path_to_root(si, path_s.data());
        int lt = path_to_root(tj, path_t.data());
        int ia = ls - 1, ib = lt - 1;
