        // if no common ancestor, trees are disconnected — shouldn't happen
        if (ia + 1 >= ls || ib + 1 >= lt) return false;

        double delta = std::numeric_limits<double>::infinity();
        int leave_child = -1, leave_par = -1;

        auto consider = [&](int child, int par, bool c2p) {
            bool backward;
            double flow;
            if (par == root || child == root) {
                int node = par == root ? child : par;
                // artificial forward: source->root, root->target
                if (node < n) { backward = !c2p; }
                else { backward = c2p; }
                // if child==root, c2p means root->par? We only call with child being the lower node.
                flow = art[node];
            } else if (par == -1) {
                return;
            } else {
                bool child_is_source = child < n;
                backward = c2p ? !child_is_source : child_is_source;
                int i = child < n ? child : par;
                int j = (child < n ? par : child) - n;
                flow = G[(size_t)i * m + j];
            }
            if (backward && flow < delta) {
                delta = flow;
                leave_child = child;
                leave_par = par;
            }
        };
        for (int k = 0; k <= ib; ++k) consider(path_t[k], path_t[k + 1], true);
        for (int k = ia; k >= 0; --k) consider(path_s[k], path_s[k + 1], false);
        if (leave_child < 0 || !std::isfinite(delta)) {
            // no capacity limit: should not happen. bail
            return false;
        }
        if (delta < 0) delta = 0;

        if (delta != 0.0) {
            G[(size_t)enter_i * m + enter_j] += delta;
            auto apply = [&](int child, int par, bool c2p) {
                if (par == root || child == root) {
                    int node = par == root ? child : par;
                    if (node < n) art[node] += c2p ? delta : -delta;
                    else art[node] += c2p ? -delta : delta;
                } else if (par == -1) {
                    return;
                } else {
                    int i = child < n ? child : par;
                    int j = (child < n ? par : child) - n;
                    bool child_is_source = child < n;
                    bool forward = c2p ? child_is_source : !child_is_source;
                    G[(size_t)i * m + j] += forward ? delta : -delta;
                }
