        if (leave_par != -1 && parent[leave_child] == leave_par) unlink(leave_par, leave_child);
        if (parent[in_node] != out_node) {
            int old = parent[in_node];
            if (old != -1) unlink(old, in_node);
            link(out_node, in_node);
