        auto pot_from = [&](int c, int u) -> double {
            if (u == root || u == -1) return 0.0;
            if (c == root) return pot[u];
            if (c < n && u >= n && u < N) return M[(size_t)c * m + (u - n)] - pot[u];
            if (u < n && c >= n && c < N) return M[(size_t)u * m + (c - n)] - pot[u];
            return pot[u];
        };
        pot[in_node] = pot_from(in_node, out_node);
        depth[in_node] = (out_node == -1 ? 0 : depth[out_node] + 1);
        stack.clear();
        stack.push_back(in_node);
        while (!stack.empty()) {
            int u = stack.back(); stack.pop_back();
            for (int c = head[u]; c != -1; c = next[c]) {
                depth[c] = depth[u] + 1;
                pot[c] = pot_from(c, u);
                stack.push_back(c);
            }
        }
