    }

    // Full scan pricing into candidate list, keep most violated too.
    int price_full(int& best_i, int& best_j) {
        ci.clear(); cj.clear();
        best_i = -1; best_j = -1;
        double best = -tol;
        for (int i = 0; i < n; ++i) {
            const double* row = M + (size_t)i * m;
            double ui = pot[i];
            const double* v = pot.data() + n;
            for (int j = 0; j < m; ++j) {
                double rc = row[j] - ui - v[j];
                if (rc < -tol) {
                    if ((int)ci.size() < cand_cap) { ci.push_back(i); cj.push_back(j); }
                    else {
                        // reservoir: replace a random-ish slot to keep diversity
                        int slot = (int)((size_t)i * m + j) % cand_cap;
                        ci[slot] = i; cj[slot] = j;
                    }
                    if (rc < best) { best = rc; best_i = i; best_j = j; }
                }
            }
        }
        return best_i < 0 ? 0 : 1;
    }

    bool pivot_from_list() {
        double best = -tol;
        int bi = -1, bj = -1, bidx = -1;
        int C = (int)ci.size();
        for (int k = 0; k < C; ++k) {
            int i = ci[k], j = cj[k];
            double rc = M[(size_t)i * m + j] - pot[i] - pot[n + j];
            if (rc < best) { best = rc; bi = i; bj = j; bidx = k; }
        }
        if (bi < 0) return false;
        ci[bidx] = ci.back(); ci.pop_back();
        cj[bidx] = cj.back(); cj.pop_back();
        return pivot(bi, bj);
    }

    int run(int max_iter) {
        init_nw();
        int iters = 0;
        int pivots_since_price = 1000000;
        const int block = 40;
        while (iters < max_iter) {
            if (ci.empty() || pivots_since_price >= block) {
                int bi, bj;
                int found = price_full(bi, bj);
                if (!found) break;
                if (!pivot(bi, bj)) break;
                iters++;
                pivots_since_price = 1;
            } else {
                if (!pivot_from_list()) {
                    ci.clear();
                    continue;
                }
                iters++;
                pivots_since_price++;
            }
        }
        // clean tiny negatives
        for (size_t k = 0, K = (size_t)n * m; k < K; ++k) if (G[k] < 0 && G[k] > -1e-10) G[k] = 0;
        return iters;
    }
};

extern "C" {
int network_simplex(const double* a, const double* b, const double* M,
                    int n, int m, double* G, int max_iter, int) {
    Solver s(a, b, M, G, n, m);
    return s.run(max_iter);
}
}
