// Jonker-Volgenant / LAPJV for square dense assignment, double costs.
// Adapted from the classic lapjv algorithm (Jonker & Volgenant 1987).
// Returns column index for each row.
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <limits>
#include <algorithm>

static constexpr double INF = 1e18;

// cost is row-major n*n
extern "C" int lapjv(const double* cost, int n, int* rowsol, double* u_out, double* v_out) {
    // x[i] = column assigned to row i, y[j] = row assigned to column j
    std::vector<int> x(n, -1), y(n, -1);
    std::vector<double> u(n, 0.0), v(n, 0.0);
    std::vector<double> d(n);
    std::vector<int> pred(n), free_rows;
    std::vector<char> unique(n, 1);

    // COLUMN REDUCTION
    for (int i = n - 1; i >= 0; --i) {
        const double* row = cost + (size_t)i * n;
        double min1 = row[0];
        int j1 = 0;
        for (int j = 1; j < n; ++j) {
            if (row[j] < min1) { min1 = row[j]; j1 = j; }
        }
        v[j1] = min1; // will be overwritten by last row that picks j1; we do it properly below
        // standard: find two smallest, but we'll do a simpler reduction
        (void)j1;
    }
    // Proper column reduction:
    // for each column find min, subtract later via v initialization differently.
    // Use the standard JV initialization:
    std::fill(v.begin(), v.end(), INF);
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) if (row[j] < v[j]) v[j] = row[j];
    }
    // row reduction + greedy assignment
    for (int i = n - 1; i >= 0; --i) {
        const double* row = cost + (size_t)i * n;
        double min1 = INF, min2 = INF;
        int j1 = -1;
        for (int j = 0; j < n; ++j) {
            double red = row[j] - v[j];
            if (red < min1) { min2 = min1; min1 = red; j1 = j; }
            else if (red < min2) min2 = red;
        }
        u[i] = min1;
        if (y[j1] == -1) {
            x[i] = j1; y[j1] = i;
        } else {
            // not unique or taken: if another row already has it, mark and free this row
            unique[j1] = 0;
            free_rows.push_back(i);
        }
    }
    // AUGMENT free rows. Reduction transfer for columns with unique assignment
    for (int j = 0; j < n; ++j) {
        if (y[j] != -1 && unique[j]) {
            int i = y[j];
            const double* row = cost + (size_t)i * n;
            double min2 = INF;
            for (int j2 = 0; j2 < n; ++j2) if (j2 != j) {
                double red = row[j2] - u[i] - v[j2];
                if (red < min2) min2 = red;
            }
            if (min2 > 0 && min2 < INF / 2) v[j] -= min2;
        }
    }

    // Recompute free rows in order (low index first tends to be fine)
    free_rows.clear();
    for (int i = 0; i < n; ++i) if (x[i] < 0) free_rows.push_back(i);

    std::vector<int> cols(n);
    std::vector<char> seen(n);

    auto augment = [&](int freerow) -> bool {
        // Dijkstra-like shortest augmenting path
        std::fill(d.begin(), d.end(), INF);
        std::fill(pred.begin(), pred.end(), -1);
        std::fill(seen.begin(), seen.end(), 0);
        int last_j = -1;
        int nscan = 0;
        // initialize distances from free row
        {
            const double* row = cost + (size_t)freerow * n;
            double ui = u[freerow];
            for (int j = 0; j < n; ++j) {
                d[j] = row[j] - ui - v[j];
                pred[j] = freerow;
                cols[nscan++] = j;
            }
        }
        int ready = 0; // scanned prefix of cols? we'll select min each time among unvisited
        while (true) {
            double mind = INF;
            int jmin = -1;
            for (int k = 0; k < n; ++k) {
                if (!seen[k] && d[k] < mind) { mind = d[k]; jmin = k; }
            }
            if (jmin < 0) return false;
            seen[jmin] = 1;
            if (y[jmin] < 0) {
                // augment
                last_j = jmin;
                // update duals
                double delta = mind;
                u[freerow] += delta;
                for (int j = 0; j < n; ++j) {
                    if (seen[j] && j != jmin) {
                        int i = y[j];
                        if (i >= 0) u[i] += delta - d[j];
                        v[j] -= delta - d[j];
                    } else if (!seen[j]) {
                        // d stays
                    }
                }
                // actually standard dual update:
                // for scanned columns j (including jmin?): v[j] += d[j] - mind, and for their rows u[i] -= d[j]-mind? 
                // Let me redo carefully after finding the path. We'll apply a known-correct update below.
                (void)delta;
                // path augmentation
                while (last_j >= 0) {
                    int i = pred[last_j];
                    int prev_j = x[i];
                    x[i] = last_j;
                    y[last_j] = i;
                    last_j = prev_j;
                    if (i == freerow) break;
                }
                return true;
            }
            // relax through matched row y[jmin]
            int i2 = y[jmin];
            const double* row = cost + (size_t)i2 * n;
            double ui = u[i2];
            // reduced cost offset: the dual-feasible distance
            double base = mind; // d[jmin] should equal mind
            for (int j = 0; j < n; ++j) if (!seen[j]) {
                double red = row[j] - ui - v[j];
                double nd = base + red - (cost[(size_t)i2 * n + jmin] - ui - v[jmin]);
                // since matched edge should have reduced cost 0 if duals maintained: cost[i2,jmin]-ui-v[jmin] == 0
                // nd = base + red
                nd = base + red;
                if (nd < d[j]) {
                    d[j] = nd;
                    pred[j] = i2;
                }
            }
            (void)ready;
        }
    };

    // The dual update inside augment is incomplete. Use a cleaner implementation.
    // We'll replace with a well-known formulation below by not using this lambda.
    (void)augment;

    // ---- clean implementation ----
    // Reset assignments from the reduction? Keep them.
    // Fix duals to be feasible for current matching, then augment.

    // Recompute u from matching: u[i] = cost[i, x[i]] - v[x[i]] for assigned, min reduced for free.
    for (int i = 0; i < n; ++i) {
        if (x[i] >= 0) u[i] = cost[(size_t)i * n + x[i]] - v[x[i]];
    }

    std::vector<int> scan(n);
    for (int fi = 0; fi < (int)free_rows.size(); ++fi) {
        int f = free_rows[fi];
        std::fill(d.begin(), d.end(), INF);
        std::fill(pred.begin(), pred.end(), -1);
        std::fill(seen.begin(), seen.end(), 0);
        const double* frow = cost + (size_t)f * n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j]; // u[f] absorbed into a constant; we set u[f] at the end
            pred[j] = f;
        }
        int end_j = -1;
        double mind_final = 0;
        while (true) {
            double mind = INF;
            int jmin = -1;
            for (int j = 0; j < n; ++j) if (!seen[j] && d[j] < mind) { mind = d[j]; jmin = j; }
            if (jmin < 0) return -1;
            seen[jmin] = 1;
            if (y[jmin] < 0) { end_j = jmin; mind_final = mind; break; }
            int i2 = y[jmin];
            const double* row = cost + (size_t)i2 * n;
            int jmatch = x[i2];
            double cred = row[jmatch] - v[jmatch]; // == u[i2] if maintained, but use direct
            // slack to other columns relative to matched column
            for (int j = 0; j < n; ++j) if (!seen[j]) {
                double nd = mind + (row[j] - v[j]) - cred;
                if (nd < d[j]) { d[j] = nd; pred[j] = i2; }
            }
        }
        // dual update so reduced costs stay nonnegative and matched edges stay tight
        // u[f] effectively becomes mind_final (since we omitted u[f], distances are cost - v)
        u[f] = mind_final;
        for (int j = 0; j < n; ++j) if (seen[j]) {
            int i = y[j];
            // columns on the scanned set (except the final free one, which has no row yet)
            if (j != end_j && i >= 0) {
                u[i] += mind_final - d[j];
                v[j] -= mind_final - d[j];
            }
        }
        v[end_j] -= mind_final - d[end_j]; // d[end_j]==mind_final so this is 0. OK.
        // augment
        int j = end_j;
        while (true) {
            int i = pred[j];
            int pj = x[i];
            x[i] = j;
            y[j] = i;
            if (i == f) break;
            j = pj;
        }
    }

    for (int i = 0; i < n; ++i) rowsol[i] = x[i];
    if (u_out) std::memcpy(u_out, u.data(), sizeof(double) * n);
    if (v_out) std::memcpy(v_out, v.data(), sizeof(double) * n);
    return 0;
}
