// Cache-friendlier Jonker-Volgenant for square dense min-cost assignment.
// Column-major cost internally. Dual variables u (rows), v (cols).
// Multiple augmentations, Dijkstra with a scan of unvisited columns.
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>

extern "C" int lap_solve(const double* cost_rowmajor, int n, int* rowsol) {
    const size_t N = (size_t)n * n;
    std::vector<double> C(N); // column-major: C[j*n + i]
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            C[(size_t)j * n + i] = cost_rowmajor[(size_t)i * n + j];

    std::vector<double> v(n, 0.0), u(n, 0.0);
    std::vector<int> y(n, -1), x(n, -1); // y[j]=row, x[i]=col
    std::vector<double> d(n);
    std::vector<int> pred(n);
    std::vector<int> parent_col(n);
    std::vector<char> seen(n);
    std::vector<int> free_rows;
    free_rows.reserve(n);

    // column minima
    for (int j = 0; j < n; ++j) {
        const double* col = C.data() + (size_t)j * n;
        double m = col[0];
        for (int i = 1; i < n; ++i) if (col[i] < m) m = col[i];
        v[j] = m;
    }

    // greedy row assignment from the bottom (JV style), plus reduction transfer
    std::vector<char> col_free(n, 1);
    for (int i = n - 1; i >= 0; --i) {
        double min1 = std::numeric_limits<double>::infinity();
        double min2 = min1;
        int j1 = 0;
        for (int j = 0; j < n; ++j) {
            double red = C[(size_t)j * n + i] - v[j];
            if (red < min1) { min2 = min1; min1 = red; j1 = j; }
            else if (red < min2) min2 = red;
        }
        u[i] = min1;
        if (col_free[j1]) {
            col_free[j1] = 0;
            x[i] = j1;
            y[j1] = i;
            // reduction transfer
            if (min2 < 1e300) v[j1] -= (min2 - min1);
        } else {
            free_rows.push_back(i);
        }
    }
    std::reverse(free_rows.begin(), free_rows.end());

    // augment each free row
    std::vector<int> order(n);
    for (int fidx = 0; fidx < (int)free_rows.size(); ++fidx) {
        int f = free_rows[fidx];
        std::fill(seen.begin(), seen.end(), 0);
        // d[j] = reduced cost from free row, ignoring u[f] (added at end)
        for (int j = 0; j < n; ++j) {
            d[j] = C[(size_t)j * n + f] - v[j];
            pred[j] = f;
        }
        int endj = -1;
        double mind = 0;
        // Dijkstra: each step pick min unvisited. n is 600, this is n^2 per augmentation.
        // Number of free rows is the thing to shrink.
        while (true) {
            mind = std::numeric_limits<double>::infinity();
            int jmin = -1;
            for (int j = 0; j < n; ++j) {
                if (!seen[j] && d[j] < mind) { mind = d[j]; jmin = j; }
            }
            seen[jmin] = 1;
            if (y[jmin] < 0) { endj = jmin; break; }
            int i2 = y[jmin];
            int jm = x[i2];
            double cred = C[(size_t)jm * n + i2] - v[jm];
            for (int j = 0; j < n; ++j) if (!seen[j]) {
                double nd = mind + C[(size_t)j * n + i2] - v[j] - cred;
                if (nd < d[j]) { d[j] = nd; pred[j] = i2; }
            }
        }
        // dual update
        u[f] = mind;
        for (int j = 0; j < n; ++j) if (seen[j]) {
            double diff = mind - d[j];
            if (j != endj) {
                int i = y[j];
                u[i] += diff;
            }
            v[j] -= diff;
        }
        // augment along pred
        int j = endj;
        while (true) {
            int i = pred[j];
            int pj = x[i];
            x[i] = j;
            y[j] = i;
            if (i == f) break;
            j = pj;
        }
    }

    for (int i = 0; i < n; ++i) rowsol[i] = x[i];
    return (int)free_rows.size();
}
