// Tuned network simplex for dense square OT.
// NW-corner basis, parent-index tree (no child lists), candidate list refreshed by sampling.
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <cstdlib>

struct NS {
    int n, root, nnodes;
    const double* a;
    const double* b;
    const double* M;
    double* G;
    double tol;

    std::vector<int> parent;     // parent or -1
    std::vector<int> depth;
    std::vector<double> pot;
    std::vector<int> pathbuf;
    std::vector<int> rpath;

    // candidates
    std::vector<int> ci, cj;
    int cap;

    NS(const double* a_, const double* b_, const double* M_, double* G_, int n_)
        : n(n_), root(-1), nnodes(2 * n_), a(a_), b(b_), M(M_), G(G_), tol(1e-12) {
        parent.assign(nnodes, -1);
        depth.assign(nnodes, 0);
        pot.assign(nnodes, 0.0);
        pathbuf.resize(nnodes);
        rpath.reserve(nnodes);
        cap = std::min(n * n, std::max(8192, 16 * n));
        ci.reserve(cap);
        cj.reserve(cap);
    }

    void init() {
        std::memset(G, 0, sizeof(double) * (size_t)n * n);
        std::fill(parent.begin(), parent.end(), -1);
        // NW corner with degenerate edges when both exhausted, WITHOUT creating cycles:
        // when both hit zero, advance i only; next edge (i, j) is degenerate and connects new source.
        std::vector<double> as(a, a + n), bs(b, b + n);
        struct E { int i, j; };
        std::vector<E> edges;
        edges.reserve(2 * n);
        int i = 0, j = 0;
        while (i < n && j < n) {
            double f = as[i] < bs[j] ? as[i] : bs[j];
            G[(size_t)i * n + j] += f;
            edges.push_back({i, j});
            as[i] -= f; bs[j] -= f;
            if (as[i] <= 1e-15 * (std::abs(a[i]) + 1)) as[i] = 0;
            if (bs[j] <= 1e-15 * (std::abs(b[j]) + 1)) bs[j] = 0;
            if (as[i] == 0 && bs[j] == 0) {
                if (i + 1 < n) ++i;
                else if (j + 1 < n) ++j;
                else break;
            } else if (as[i] == 0) ++i;
            else ++j;
        }
        // spanning tree via BFS, root = source 0
        std::vector<std::vector<int>> adjS(n), adjT(n);
        for (auto e : edges) { adjS[e.i].push_back(e.j); adjT[e.j].push_back(e.i); }
        std::vector<char> vis(nnodes, 0);
        parent[0] = -1;
        pot[0] = 0;
        depth[0] = 0;
        vis[0] = 1;
        std::vector<int> q;
        q.push_back(0);
        for (size_t qh = 0; qh < q.size(); ++qh) {
            int u = q[qh];
            if (u < n) {
                for (int jj : adjS[u]) {
                    int node = n + jj;
                    if (vis[node]) continue;
                    vis[node] = 1;
                    parent[node] = u;
                    pot[node] = M[(size_t)u * n + jj] - pot[u];
                    depth[node] = depth[u] + 1;
                    q.push_back(node);
                }
            } else {
                int jj = u - n;
                for (int ii : adjT[jj]) {
                    if (vis[ii]) continue;
                    vis[ii] = 1;
                    parent[ii] = u;
                    pot[ii] = M[(size_t)ii * n + jj] - pot[u];
                    depth[ii] = depth[u] + 1;
                    q.push_back(ii);
                }
            }
        }
    }

    // write path from x to root into buf, return length. buf[0]=x ... buf[len-1]=root
    int path(int x, int* buf) const {
        int len = 0;
        while (x != -1) { buf[len++] = x; x = parent[x]; }
        return len;
    }

    bool pivot(int ei, int ej) {
        int si = ei;
        int tj = n + ej;
        // paths on stack-ish buffers: use pathbuf split
        // We'll use two halves... nnodes can be 1200, fine to allocate thread-local static? use members carefully.
        // Use local vectors reserved — allocation avoided if we reuse rpath-sized buffers stored as members.
        // path_s and path_t as part of pathbuf: first call uses a side vector.
        static thread_local std::vector<int> ps, pt;
        if ((int)ps.size() < nnodes) { ps.resize(nnodes); pt.resize(nnodes); }
        int ls = path(si, ps.data());
        int lt = path(tj, pt.data());
        int ia = ls - 1, ib = lt - 1;
        while (ia >= 0 && ib >= 0 && ps[ia] == pt[ib]) { --ia; --ib; }
        if (ia + 1 >= ls || ib + 1 >= lt) return false;

        double delta = std::numeric_limits<double>::infinity();
        int lc = -1, lp = -1;
        auto consider = [&](int child, int par, bool c2p) {
            if (par < 0) return;
            bool child_is_source = child < n;
            bool backward = c2p ? !child_is_source : child_is_source;
            if (!backward) return;
            int i = child_is_source ? child : par;
            int j = child_is_source ? (par - n) : (child - n);
            double flow = G[(size_t)i * n + j];
            if (flow < delta) { delta = flow; lc = child; lp = par; }
        };
        for (int k = 0; k <= ib; ++k) consider(pt[k], pt[k + 1], true);
        for (int k = ia; k >= 0; --k) consider(ps[k], ps[k + 1], false);
        if (lc < 0 || !std::isfinite(delta)) return false;
        if (delta < 0) delta = 0;

        if (delta != 0.0) {
            G[(size_t)ei * n + ej] += delta;
            auto apply = [&](int child, int par, bool c2p) {
                if (par < 0) return;
                bool child_is_source = child < n;
                bool forward = c2p ? child_is_source : !child_is_source;
                int i = child_is_source ? child : par;
                int j = child_is_source ? (par - n) : (child - n);
                G[(size_t)i * n + j] += forward ? delta : -delta;
            };
            for (int k = 0; k <= ib; ++k) apply(pt[k], pt[k + 1], true);
            for (int k = ia; k >= 0; --k) apply(ps[k], ps[k + 1], false);
        }
        // zero leaving edge
        {
            bool child_is_source = lc < n;
            int i = child_is_source ? lc : lp;
            int j = child_is_source ? (lp - n) : (lc - n);
            G[(size_t)i * n + j] = 0.0;
        }

        // which endpoint is in subtree of lc
        auto desc = [&](int node, int sub) {
            for (int x = node; x != -1; x = parent[x]) if (x == sub) return true;
            return false;
        };
        bool si_in = desc(si, lc);
        int in_node, out_node;
        if (si_in) { in_node = si; out_node = tj; }
        else { in_node = tj; out_node = si; }

        // reverse parent links from in_node up to lc
        rpath.clear();
        for (int x = in_node; x != -1; x = parent[x]) {
            rpath.push_back(x);
            if (x == lc) break;
        }
        // rpath[0]=in_node ... rpath.back()=lc, parents point toward root (toward higher index)
        for (int k = (int)rpath.size() - 1; k >= 1; --k) {
            parent[rpath[k]] = rpath[k - 1];
        }
        parent[in_node] = out_node;

        // update pot + depth down the reversed subtree.
        // Children are not stored. The subtree is the set of nodes whose parent-chain hits in_node.
        // After rewiring, nodes that were descendants of the old subtree still have parent pointers
        // within the subtree EXCEPT the reversed path. Nodes off the path still point to their old parents,
        // which are in the subtree. Good.
        // We need to visit all descendants. Without child lists, scan all nodes — nnodes=1200, cheap vs pricing!
        auto pot_from = [&](int c, int u) -> double {
            if (u < 0) return 0.0;
            if (c < n && u >= n) return M[(size_t)c * n + (u - n)] - pot[u];
            if (u < n && c >= n) return M[(size_t)u * n + (c - n)] - pot[u];
            return pot[u];
        };
        pot[in_node] = pot_from(in_node, out_node);
        depth[in_node] = depth[out_node] + 1;

        // Multi-pass relaxation over nodes whose parent has been updated. Since tree depth <= nnodes,
        // a queue built by scanning once per level is ok but scanning all nodes a few times:
        // Build child lists on the fly for just this update by one scan.
        std::vector<int> head(nnodes, -1), nxt(nnodes, -1);
        for (int node = 0; node < nnodes; ++node) {
            int p = parent[node];
            if (p >= 0) { nxt[node] = head[p]; head[p] = node; }
        }
        // BFS from in_node
        std::vector<int> st;
        st.push_back(in_node);
        for (size_t qh = 0; qh < st.size(); ++qh) {
            int u = st[qh];
            for (int c = head[u]; c != -1; c = nxt[c]) {
                depth[c] = depth[u] + 1;
                pot[c] = pot_from(c, u);
                st.push_back(c);
            }
        }
        return true;
    }

    int price(int& bi, int& bj, int stride) {
        ci.clear(); cj.clear();
        bi = -1; bj = -1;
        double best = -tol;
        int found = 0;
        for (int i = 0; i < n; i += stride) {
            const double* row = M + (size_t)i * n;
            double ui = pot[i];
            const double* vv = pot.data() + n;
            for (int j = 0; j < n; ++j) {
                double rc = row[j] - ui - vv[j];
                if (rc < best) {
                    best = rc; bi = i; bj = j;
                }
                if (rc < -tol && (int)ci.size() < cap) {
                    ci.push_back(i); cj.push_back(j); found++;
                }
            }
        }
        return found;
    }

    bool pivot_list() {
        double best = -tol;
        int bi = -1, bj = -1, bk = -1;
        int C = (int)ci.size();
        const double* vv = pot.data() + n;
        for (int k = 0; k < C; ++k) {
            int i = ci[k], j = cj[k];
            double rc = M[(size_t)i * n + j] - pot[i] - vv[j];
            if (rc < best) { best = rc; bi = i; bj = j; bk = k; }
        }
        if (bi < 0) return false;
        ci[bk] = ci.back(); ci.pop_back();
        cj[bk] = cj.back(); cj.pop_back();
        return pivot(bi, bj);
    }

    int run(int max_iter) {
        init();
        int iters = 0;
        int since = 1000;
        const int block = 30;
        while (iters < max_iter) {
            if (ci.empty() || since >= block) {
                int bi, bj;
                // stride 1 full pricing
                int found = price(bi, bj, 1);
                if (!found) break;
                if (!pivot(bi, bj)) break;
                ++iters; since = 1;
            } else {
                if (!pivot_list()) { ci.clear(); continue; }
                ++iters; ++since;
            }
        }
        for (size_t k = 0, K = (size_t)n * n; k < K; ++k)
            if (G[k] < 0 && G[k] > -1e-9) G[k] = 0;
        return iters;
    }
};

extern "C" int network_simplex(const double* a, const double* b, const double* M,
                               int n, int m, double* G, int max_iter, int) {
    if (n != m) return -1;
    NS s(a, b, M, G, n);
    return s.run(max_iter);
}
