// Epsilon-scaling auction for dense square min-cost assignment (Bertsekas).
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>

extern "C" int auction_solve(const double* M, int n, int* rowsol, double eps_target) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assign(n, -1);
    std::vector<int> free_rows;
    free_rows.reserve(n);

    double maxc = 0.0;
    for (size_t k = 0, K = (size_t)n * n; k < K; ++k) if (M[k] > maxc) maxc = M[k];
    double eps = maxc / 4.0;
    if (eps < eps_target) eps = eps_target;
    int total_bids = 0;
    const int bid_limit = n * n * 8;

    while (eps >= eps_target * 0.999) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        free_rows.clear();
        for (int i = 0; i < n; ++i) free_rows.push_back(i);
        // stack-style
        while (!free_rows.empty()) {
            int i = free_rows.back();
            free_rows.pop_back();
            const double* row = M + (size_t)i * n;
            // best and second best reduced cost = M + price
            double best = std::numeric_limits<double>::infinity();
            double second = best;
            int jbest = 0;
            for (int j = 0; j < n; ++j) {
                double red = row[j] + price[j];
                if (red < best) { second = best; best = red; jbest = j; }
                else if (red < second) second = red;
            }
            double bid = second - best + eps;
            price[jbest] += bid;
            int prev = owner[jbest];
            if (prev == i) {
                // already owner, nothing
            } else {
                owner[jbest] = i;
                assign[i] = jbest;
                if (prev >= 0) {
                    assign[prev] = -1;
                    free_rows.push_back(prev);
                }
            }
            if (++total_bids > bid_limit) {
                for (int r = 0; r < n; ++r) rowsol[r] = assign[r];
                return -total_bids;
            }
        }
        eps *= 0.25;
        if (eps < eps_target) break;
    }
    for (int r = 0; r < n; ++r) rowsol[r] = assign[r];
    return total_bids;
}
