// Forward-reverse epsilon-scaling auction (Bertsekas) for min-cost assignment.
// Minimization form: reduced cost = M[i,j] + price[j] - profit[i], we store price only
// and compute profit on the fly as the best reduced cost.
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <cstring>

extern "C" int auction_fr(const double* M, int n, int* rowsol, double eps_target, double factor) {
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);   // col -> row
    std::vector<int> assign(n, -1);  // row -> col
    std::vector<int> free_rows;
    std::vector<int> free_cols;
    free_rows.reserve(n);
    free_cols.reserve(n);

    double maxc = 0;
    for (size_t k = 0, K = (size_t)n * n; k < K; ++k) if (M[k] > maxc) maxc = M[k];
    double eps = std::max(maxc / 2.0, eps_target);

    auto assign_all_check = [&]() {
        for (int i = 0; i < n; ++i) if (assign[i] < 0) return false;
        return true;
    };

    int bids = 0;
    const int limit = n * 400;

    while (eps + 1e-18 >= eps_target) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        free_rows.clear();
        for (int i = 0; i < n; ++i) free_rows.push_back(i);

        int guard = 0;
        while (!free_rows.empty() && guard < limit) {
            // FORWARD bids for a batch of free rows (one each)
            // Process all current free rows once (Jacobi-like within round, Gauss-Seidel across)
            int batch = (int)free_rows.size();
            // Gauss-Seidel: one row at a time is more stable; do all of them
            for (int t = 0; t < batch && !free_rows.empty(); ++t) {
                int i = free_rows.back(); free_rows.pop_back();
                if (assign[i] >= 0) continue;
                const double* row = M + (size_t)i * n;
                double best = std::numeric_limits<double>::infinity(), second = best;
                int jbest = 0;
                for (int j = 0; j < n; ++j) {
                    double red = row[j] + price[j];
                    if (red < best) { second = best; best = red; jbest = j; }
                    else if (red < second) second = red;
                }
                price[jbest] += (second - best) + eps;
                int prev = owner[jbest];
                owner[jbest] = i;
                assign[i] = jbest;
                if (prev >= 0 && prev != i) {
                    assign[prev] = -1;
                    free_rows.push_back(prev);
                }
                ++bids; ++guard;
            }
            if (free_rows.empty()) break;

            // REVERSE auction: unassigned columns bid for rows.
            // A column j is free if owner[j] < 0.
            // Profit of row i is -best_reduced? For min-cost, reverse:
            // column j looks for the row with smallest (M[i,j] + price[j] - profit_i) ... 
            // Simpler reverse used in practice:
            //   pi[i] = price[assign[i]] + M[i, assign[i]]   (cost level of assigned row)
            //   free column j seeks row i minimizing M[i,j] - pi[i], bids to become better.
            // We'll implement the standard reverse for minimization:
            // Let profit[i] for assigned rows be the reduced cost they achieved? 
            //
            // From Bertsekas forward-reverse (minimization variant used by many codes):
            // price is the dual of columns. Row profit u[i] = min_j (M[i,j] + price[j]) for assigned,
            // and assigned column satisfies M[i,j]+price[j] <= u[i] + eps.
            // Reverse: an unassigned column j bids for a row i, offering to raise? This is easy to get wrong.
            // Skip reverse if not clearly beneficial; the forward-only already works.
            break;
        }
        if (!free_rows.empty()) {
            for (int i = 0; i < n; ++i) rowsol[i] = assign[i];
            return -bids;
        }
        if (eps <= eps_target) break;
        eps *= factor;
        if (eps < eps_target) eps = eps_target;
    }
    for (int i = 0; i < n; ++i) rowsol[i] = assign[i];
    return bids;
}
