            double best, second;
            int jbest;
            scan_best2(M + (size_t)i * n, price.data(), n, best, second, jbest);
            price[jbest] += (second - best) + eps;
            int prev = owner[jbest];
            owner[jbest] = i;
            assign[i] = jbest;
            if (prev >= 0 && prev != i) {
                assign[prev] = -1;
                free_rows[sp++] = prev;
            }
            if (++total > limit) {
                for (int r = 0; r < n; ++r) rowsol[r] = assign[r];
                return -total;
            }
        }
        if (eps <= eps_target * 1.0000001) break;
        double next = eps * factor;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
    for (int r = 0; r < n; ++r) rowsol[r] = assign[r];
    return total;
}
