// Cost-scaling assignment (push-relabel style) for dense square integer costs.
// Based on Goldberg-Kennedy cost scaling / successive shortest paths with potentials,
// specialized to a permutation (unit supplies).
//
// We scale costs to int64, solve exactly on scaled costs, return assignment.
// Algorithm: epsilon-optimality refinement via Dijkstra augmentations is JV.
// This file implements the "cost scaling auction" which is similar but uses
// admissibility: only edges with reduced cost < eps are considered, maintained
// with a price, and we use a stack of admissible candidates — still O(n) scan
// unless we restrict.
//
// Practical approach used by several fast LAP codes (e.g. Volgenant, and the
// "scaling push-relabel" of Goldberg): 
//   For epsilon from large to 1:
//     while some node is not epsilon-optimal, push along admissible edges.
//
// I'll implement Goldberg's cost-scaling for the assignment problem following
// the description in "An Efficient Cost Scaling Algorithm for the Assignment Problem"
// (Goldberg & Kennedy), simplified:
//   - bipartite, unit supplies
//   - refine(eps): make the matching eps-optimal and perfect
//
// Given time, a well-known fast method is the Jonker-Volgenant with column-reduction
// which scipy already does in ~12ms. Beating 20x (2ms) needs either fewer memory
// passes or a fundamentally cheaper problem.
//
// TRY: exploit that points are in [0,1]^2 and cost is euclidean. The optimal
// assignment of uniform measures between two point sets is the matching of points.
// We can compute it from coordinates if we recover them — we only have the cost matrix.
//
// This file instead implements a *restricted* JV: Dijkstra only scans columns that
// are among the k nearest in reduced cost, expanding k on failure. For geometric
// costs, augmenting paths are short in the kNN graph.
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <cstring>
#include <queue>

struct MinHeap {
    std::vector<std::pair<double,int>> h;
    void clear() { h.clear(); }
    bool empty() const { return h.empty(); }
    void push(double d, int j) { h.emplace_back(d, j); std::push_heap(h.begin(), h.end(), std::greater<>()); }
    std::pair<double,int> pop() {
        std::pop_heap(h.begin(), h.end(), std::greater<>());
        auto r = h.back(); h.pop_back(); return r;
    }
};

// kNN lists precomputed per row (indices of k smallest costs)
extern "C" int lap_knn(const double* M, int n, const int* knn, int k, int* rowsol) {
    // knn: n * k row-major, knn[i*k + t] = column
    std::vector<double> v(n, 0.0), u(n, 0.0);
    std::vector<int> y(n, -1), x(n, -1);
    std::vector<double> dist(n);
    std::vector<int> pred(n);
    std::vector<int> ver(n, 0);
    int version = 0;
    MinHeap heap;

    // init v = col min over full matrix (one pass)
    for (int j = 0; j < n; ++j) v[j] = std::numeric_limits<double>::infinity();
    for (int i = 0; i < n; ++i) {
        const double* row = M + (size_t)i * n;
        for (int j = 0; j < n; ++j) if (row[j] < v[j]) v[j] = row[j];
    }
    // greedy on knn
    for (int i = n - 1; i >= 0; --i) {
        const double* row = M + (size_t)i * n;
        const int* nb = knn + (size_t)i * k;
        double best = std::numeric_limits<double>::infinity();
        int jb = nb[0];
        for (int t = 0; t < k; ++t) {
            int j = nb[t];
            double red = row[j] - v[j];
            if (red < best) { best = red; jb = j; }
        }
        u[i] = best;
        if (y[jb] < 0) { y[jb] = i; x[i] = jb; }
    }
    std::vector<int> free_rows;
    for (int i = 0; i < n; ++i) if (x[i] < 0) free_rows.push_back(i);

    auto augment = [&](int f) -> bool {
        ++version;
        heap.clear();
        const double* frow = M + (size_t)f * n;
        const int* fnb = knn + (size_t)f * k;
        for (int t = 0; t < k; ++t) {
            int j = fnb[t];
            dist[j] = frow[j] - v[j];
            pred[j] = f;
            ver[j] = version;
            heap.push(dist[j], j);
        }
        // also seed with a few global? start with knn only
        int endj = -1;
        double mind = 0;
        std::vector<int> scanned;
        scanned.reserve(64);
        while (!heap.empty()) {
            auto [d, j] = heap.pop();
            if (ver[j] != version || d > dist[j] + 1e-15) continue;
            if (d > dist[j] + 1e-18 && ver[j] == version) {
                // stale
            }
            // mark scanned by setting ver to -version? use a scanned flag array via pred sign? 
            // Use dist sentinel: set dist[j] = -1 after scan? Can't, need dist for dual.
            // separate scanned version
            scanned.push_back(j);
            // mark by flipping: we'll use a scanver array
            // (handled below with scanver)
            mind = d;
            if (y[j] < 0) { endj = j; break; }
            int i2 = y[j];
            int jm = x[i2];
            double cred = M[(size_t)i2 * n + jm] - v[jm];
            const int* nb = knn + (size_t)i2 * k;
            const double* row = M + (size_t)i2 * n;
            for (int t = 0; t < k; ++t) {
                int j2 = nb[t];
                double nd = d + row[j2] - v[j2] - cred;
                if (ver[j2] != version || nd < dist[j2]) {
                    dist[j2] = nd;
                    pred[j2] = i2;
                    ver[j2] = version;
                    heap.push(nd, j2);
                }
            }
        }
        if (endj < 0) return false;
        // dual update over scanned columns: those with ver==version and dist<=mind
        u[f] = mind;
        for (int j = 0; j < n; ++j) if (ver[j] == version && dist[j] <= mind + 1e-15) {
            double diff = mind - dist[j];
            if (j != endj && y[j] >= 0) u[y[j]] += diff;
            v[j] -= diff;
        }
        int j = endj;
        while (true) {
            int i = pred[j];
            int pj = x[i];
            x[i] = j; y[j] = i;
            if (i == f) break;
            j = pj;
        }
        return true;
    };

    for (int f : free_rows) {
        if (!augment(f)) {
            // failed on knn graph
            for (int i = 0; i < n; ++i) rowsol[i] = x[i];
            return -1;
        }
    }
    for (int i = 0; i < n; ++i) rowsol[i] = x[i];
    return (int)free_rows.size();
}
ENDCPP
