// Parallel Jacobi auction: all free rows bid simultaneously, each column takes the
// bidder with the largest price increase. May need more iterations but parallelizes.
extern "C" int auction_jacobi(const double* M, int n, int* rowsol, double eps_target, int nthreads) {
    omp_set_num_threads(nthreads);
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assign(n, -1);
    std::vector<int> free_rows(n);
    std::vector<Bid> bids(n);
    std::vector<int> col_best_bidder(n);
    std::vector<double> col_best_inc(n);

    double maxc = 0;
    for (size_t k = 0, K=(size_t)n*n; k<K; ++k) if (M[k] > maxc) maxc = M[k];
    double eps = maxc * 0.05;
    if (eps < eps_target) eps = eps_target;
    int rounds = 0;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        int guard = 0;
        while (nfree > 0 && guard < n * 50) {
            // compute bids in parallel
            #pragma omp parallel for schedule(static)
            for (int t = 0; t < nfree; ++t) {
                int i = free_rows[t];
                best2(M + (size_t)i * n, price.data(), n, bids[i]);
