            // apply winning bids
            std::vector<int> newly_free;
            newly_free.reserve(nfree);
            std::vector<char> got(n, 0);
            for (int j = 0; j < n; ++j) {
                int i = col_best_bidder[j];
                if (i < 0) continue;
                price[j] += col_best_inc[j];
                int prev = owner[j];
                owner[j] = i;
                assign[i] = j;
                got[i] = 1;
                if (prev >= 0 && prev != i) {
                    assign[prev] = -1;
                    newly_free.push_back(prev);
                }
