// Cost-scaling push-relabel for dense assignment, geometric-friendly.
// Integer costs. Admissible edges limited to k nearest neighbors, expanded if needed.
// This is a partial implementation used to measure whether local admissible pushes
// can finish fast. If the kNN graph doesn't contain a perfect matching of near-optimal
// cost, we fall back by increasing k.
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <cstring>
#include <limits>

// For now, a successive-shortest-path with potentials using a DIAL-like bucket
// on scaled integer reduced costs, restricted to kNN, with fallback to full scan
// only for the current Dijkstra (not the whole algorithm). The idea: most Dijkstra
// relaxations hit the kNN; if the heap empties before finding a free column, do one
// full relaxation from scanned rows.

struct Heap {
    std::vector<std::pair<long long, int>> h;
    void clear() { h.clear(); }
    bool empty() const { return h.empty(); }
    void push(long long d, int j) {
        h.emplace_back(d, j);
        std::push_heap(h.begin(), h.end(), std::greater<>());
    }
    std::pair<long long, int> pop() {
        std::pop_heap(h.begin(), h.end(), std::greater<>());
        auto r = h.back(); h.pop_back(); return r;
    }
};

extern "C" int ssp_assign(const double* M, int n, int* rowsol, int scale) {
    // integer costs
    std::vector<int> C(n * (size_t)n);
    for (size_t k = 0, K = (size_t)n * n; k < K; ++k) {
        double v = M[k] * scale;
        C[k] = (int)std::llround(v);
    }
    std::vector<long long> pot(n, 0); // column potentials (minimization: reduced = C - pot_row + pot_col?) 
    // We'll use reduced = C[i,j] - u[i] - v[j], maintain u implicitly.
    std::vector<long long> v(n, 0);
    std::vector<int> x(n, -1), y(n, -1);
    std::vector<long long> dist(n);
    std::vector<int> pred(n);
    std::vector<int> seen_ver(n, 0);
    int version = 1;
    Heap heap;

    // init v as column minima
    for (int j = 0; j < n; ++j) {
        int m = C[j];
        for (int i = 1; i < n; ++i) {
            int c = C[(size_t)i * n + j];
            if (c < m) m = c;
        }
        v[j] = m;
    }
    // greedy
    for (int i = n - 1; i >= 0; --i) {
        long long best = std::numeric_limits<long long>::max();
        int jb = 0;
        for (int j = 0; j < n; ++j) {
            long long red = (long long)C[(size_t)i * n + j] - v[j];
            if (red < best) { best = red; jb = j; }
        }
        if (y[jb] < 0) { y[jb] = i; x[i] = jb; }
    }
    std::vector<int> free_rows;
    for (int i = 0; i < n; ++i) if (x[i] < 0) free_rows.push_back(i);

    for (int f : free_rows) {
        ++version;
        if (version == 0) { std::fill(seen_ver.begin(), seen_ver.end(), 0); version = 1; }
        heap.clear();
        for (int j = 0; j < n; ++j) {
            dist[j] = (long long)C[(size_t)f * n + j] - v[j];
            pred[j] = f;
            seen_ver[j] = version;
            heap.push(dist[j], j);
        }
        int endj = -1;
        long long mind = 0;
        std::vector<char> scanned(n, 0);
        while (!heap.empty()) {
            auto [d, j] = heap.pop();
            if (scanned[j]) continue;
            if (d != dist[j]) continue;
            scanned[j] = 1;
            mind = d;
            if (y[j] < 0) { endj = j; break; }
            int i2 = y[j];
            int jm = x[i2];
            long long cred = (long long)C[(size_t)i2 * n + jm] - v[jm];
            const int* row = C.data() + (size_t)i2 * n;
            for (int j2 = 0; j2 < n; ++j2) if (!scanned[j2]) {
                long long nd = d + (long long)row[j2] - v[j2] - cred;
                if (seen_ver[j2] != version || nd < dist[j2]) {
                    dist[j2] = nd;
                    pred[j2] = i2;
                    seen_ver[j2] = version;
                    heap.push(nd, j2);
                }
            }
        }
        if (endj < 0) return -1;
        for (int j = 0; j < n; ++j) if (scanned[j]) {
            long long diff = mind - dist[j];
            v[j] -= diff;
        }
        int j = endj;
        while (true) {
            int i = pred[j];
            int pj = x[i];
            x[i] = j; y[j] = i;
            if (i == f) break;
            j = pj;
        }
    }
    for (int i = 0; i < n; ++i) rowsol[i] = x[i];
    return (int)free_rows.size();
}
