#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <cstring>
#include <thread>
#include <atomic>
#include <immintrin.h>

struct Bid { double best, second; int jbest; };

static inline void best2_avx(const double* __restrict row, const double* __restrict price, int n, Bid& b) {
    double best = 1e300, second = 1e300;
    int jbest = 0;
    int j = 0;
    for (; j + 8 <= n; j += 8) {
        __m256d red0 = _mm256_add_pd(_mm256_loadu_pd(row + j), _mm256_loadu_pd(price + j));
        __m256d red1 = _mm256_add_pd(_mm256_loadu_pd(row + j + 4), _mm256_loadu_pd(price + j + 4));
        alignas(32) double tmp[8];
        _mm256_store_pd(tmp, red0);
        _mm256_store_pd(tmp + 4, red1);
        #pragma unroll
        for (int k = 0; k < 8; ++k) {
            double v = tmp[k];
            if (v < best) { second = best; best = v; jbest = j + k; }
            else if (v < second) second = v;
        }
    }
    for (; j < n; ++j) {
        double v = row[j] + price[j];
        if (v < best) { second = best; best = v; jbest = j; }
        else if (v < second) second = v;
    }
    b.best = best; b.second = second; b.jbest = jbest;
}

// Persistent thread pool doing Gauss-Seidel auction is hard to parallelize.
// Instead: parallel Jacobi with price carried across epsilon phases (no full reset),
// which cuts rounds, and 4-8 threads on the bid scan.
//
// To avoid the previous crash, no shared vector resize inside threads, all buffers preallocated.

struct Pool {
    int nthreads;
    std::vector<std::thread> threads;
    std::atomic<int> phase{0};
    std::atomic<int> done{0};
    std::atomic<bool> stop{false};
    const double* M = nullptr;
    const double* price = nullptr;
    Bid* bids = nullptr;
    const int* free_rows = nullptr;
    int nfree = 0;
    int n = 0;

    explicit Pool(int nt) : nthreads(nt) {
        for (int t = 0; t < nthreads; ++t) {
            threads.emplace_back([this, t]() { worker(t); });
        }
    }
    ~Pool() {
        stop.store(true);
        phase.fetch_add(1);
        for (auto& th : threads) if (th.joinable()) th.join();
    }
    void worker(int tid) {
        int seen = 0;
        while (!stop.load(std::memory_order_relaxed)) {
            int ph = phase.load(std::memory_order_acquire);
            if (ph == seen) {
                std::this_thread::yield();
                continue;
            }
            seen = ph;
            if (stop.load()) break;
            int nfree_local = nfree;
            int chunk = (nfree_local + nthreads - 1) / nthreads;
            int lo = tid * chunk;
            int hi = std::min(nfree_local, lo + chunk);
            const double* price_l = price;
            const double* M_l = M;
            int n_l = n;
            for (int s = lo; s < hi; ++s) {
                int i = free_rows[s];
                best2_avx(M_l + (size_t)i * n_l, price_l, n_l, bids[i]);
            }
            done.fetch_add(1, std::memory_order_release);
        }
    }
    void run(const double* M_, const double* price_, Bid* bids_, const int* fr, int nfree_, int n_) {
        M = M_; price = price_; bids = bids_; free_rows = fr; nfree = nfree_; n = n_;
        done.store(0, std::memory_order_release);
        phase.fetch_add(1, std::memory_order_release);
        while (done.load(std::memory_order_acquire) < nthreads) std::this_thread::yield();
    }
};

extern "C" int auction_jacobi(const double* M, int n, int* rowsol, double eps_target, int nthreads) {
    if (nthreads < 1) nthreads = 1;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1);
    std::vector<int> assign(n, -1);
    std::vector<int> free_rows(n);
    std::vector<Bid> bids(n);
    std::vector<int> col_best_bidder(n, -1);
    std::vector<double> col_best_inc(n);
    std::vector<char> got(n);

    double maxc = 0;
    for (size_t k = 0, K = (size_t)n * n; k < K; ++k) if (M[k] > maxc) maxc = M[k];
    double eps = maxc * 0.05;
    if (eps < eps_target) eps = eps_target;

    Pool pool(nthreads);
    int rounds = 0;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        int guard = 0;
        while (nfree > 0 && guard < n * 100) {
            if (nthreads > 1 && nfree >= 32)
                pool.run(M, price.data(), bids.data(), free_rows.data(), nfree, n);
            else {
                for (int t = 0; t < nfree; ++t) {
                    int i = free_rows[t];
                    best2_avx(M + (size_t)i * n, price.data(), n, bids[i]);
                }
            }
            std::fill(col_best_bidder.begin(), col_best_bidder.end(), -1);
            std::fill(col_best_inc.begin(), col_best_inc.end(), -1.0);
            for (int t = 0; t < nfree; ++t) {
                int i = free_rows[t];
                int j = bids[i].jbest;
                double inc = (bids[i].second - bids[i].best) + eps;
                if (inc > col_best_inc[j]) { col_best_inc[j] = inc; col_best_bidder[j] = i; }
            }
            std::fill(got.begin(), got.end(), 0);
            int nnew = 0;
            // reuse free_rows buffer carefully: write newly free into a side buffer
            std::vector<int> newly;
            newly.reserve(nfree);
            for (int j = 0; j < n; ++j) {
                int i = col_best_bidder[j];
                if (i < 0) continue;
                price[j] += col_best_inc[j];
                int prev = owner[j];
                owner[j] = i;
                assign[i] = j;
                got[i] = 1;
                if (prev >= 0 && prev != i) { assign[prev] = -1; newly.push_back(prev); }
            }
            for (int t = 0; t < nfree; ++t) if (!got[free_rows[t]]) newly.push_back(free_rows[t]);
            nfree = (int)newly.size();
            if (nfree) std::memcpy(free_rows.data(), newly.data(), sizeof(int) * nfree);
            ++guard; ++rounds;
            (void)nnew;
        }
        if (nfree > 0) {
            for (int i = 0; i < n; ++i) rowsol[i] = assign[i];
            return -rounds;
        }
        if (eps <= eps_target * 1.0000001) break;
        double next = eps * 0.2;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
    for (int i = 0; i < n; ++i) rowsol[i] = assign[i];
    return rounds;
}
