// Gauss-Seidel epsilon-scaling auction with a persistent thread pool.
// Each bid scans the row in parallel chunks; threads return local best/second,
// the main thread merges and updates the price (sequential correctness).
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <thread>
#include <atomic>
#include <immintrin.h>

struct Local {
    double best, second;
    int jbest;
};

static inline void scan_range(const double* row, const double* price, int lo, int hi, Local& o) {
    double best = 1e300, second = 1e300;
    int jbest = lo;
    int j = lo;
    for (; j + 8 <= hi; j += 8) {
        __m256d r0 = _mm256_add_pd(_mm256_loadu_pd(row + j), _mm256_loadu_pd(price + j));
        __m256d r1 = _mm256_add_pd(_mm256_loadu_pd(row + j + 4), _mm256_loadu_pd(price + j + 4));
        alignas(32) double tmp[8];
        _mm256_store_pd(tmp, r0);
        _mm256_store_pd(tmp + 4, r1);
        for (int k = 0; k < 8; ++k) {
            double v = tmp[k];
            int jj = j + k;
            if (v < best) { second = best; best = v; jbest = jj; }
            else if (v < second) second = v;
        }
    }
    for (; j < hi; ++j) {
        double v = row[j] + price[j];
        if (v < best) { second = best; best = v; jbest = j; }
        else if (v < second) second = v;
    }
    o.best = best; o.second = second; o.jbest = jbest;
}

struct Pool {
    int nt;
    std::vector<std::thread> th;
    std::atomic<int> phase{0};
    std::atomic<int> done{0};
    std::atomic<bool> stop{false};
    const double* row = nullptr;
    const double* price = nullptr;
    int n = 0;
    Local* locals = nullptr;

    explicit Pool(int nthreads) : nt(nthreads) {
        for (int t = 0; t < nt; ++t) th.emplace_back([this, t]{ worker(t); });
    }
    ~Pool() {
        stop.store(true, std::memory_order_release);
        phase.fetch_add(1, std::memory_order_release);
        for (auto& x : th) if (x.joinable()) x.join();
    }
    void worker(int tid) {
        int seen = 0;
        while (!stop.load(std::memory_order_relaxed)) {
            int ph = phase.load(std::memory_order_acquire);
            if (ph == seen) { 
                // pause
                _mm_pause();
                continue;
            }
            seen = ph;
            if (stop.load(std::memory_order_relaxed)) break;
            int chunk = (n + nt - 1) / nt;
            int lo = tid * chunk;
            int hi = std::min(n, lo + chunk);
            if (lo < hi) scan_range(row, price, lo, hi, locals[tid]);
            else { locals[tid].best = 1e300; locals[tid].second = 1e300; locals[tid].jbest = 0; }
            done.fetch_add(1, std::memory_order_release);
        }
    }
    void scan(const double* row_, const double* price_, int n_, Local* locals_) {
        row = row_; price = price_; n = n_; locals = locals_;
        done.store(0, std::memory_order_relaxed);
        phase.fetch_add(1, std::memory_order_release);
        while (done.load(std::memory_order_acquire) < nt) _mm_pause();
    }
};

extern "C" int auction_gs(const double* M, int n, int* rowsol, double eps_target, int nthreads) {
    if (nthreads < 1) nthreads = 1;
    std::vector<double> price(n, 0.0);
    std::vector<int> owner(n, -1), assign(n, -1), free_rows(n);
    std::vector<Local> locals(std::max(nthreads, 1));

    double maxc = 0;
    for (size_t k = 0, K = (size_t)n * n; k < K; ++k) if (M[k] > maxc) maxc = M[k];
    double eps = maxc * 0.05;
    if (eps < eps_target) eps = eps_target;

    Pool* pool = nthreads > 1 ? new Pool(nthreads) : nullptr;
    int total = 0;
    const int limit = n * n * 4;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int sp = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        while (sp > 0) {
            int i = free_rows[--sp];
            const double* row = M + (size_t)i * n;
            double best, second; int jbest;
            if (pool) {
                pool->scan(row, price.data(), n, locals.data());
                best = 1e300; second = 1e300; jbest = 0;
                for (int t = 0; t < nthreads; ++t) {
                    double b = locals[t].best, s = locals[t].second;
                    int jb = locals[t].jbest;
                    if (b < best) {
                        // old best becomes a second candidate
                        if (best < s) s = best;
                        second = s;
                        best = b; jbest = jb;
                    } else {
                        if (b < second) second = b;
                        if (s < second) second = s;
                    }
                }
            } else {
                Local o; scan_range(row, price.data(), 0, n, o);
                best = o.best; second = o.second; jbest = o.jbest;
            }
            price[jbest] += (second - best) + eps;
            int prev = owner[jbest];
            owner[jbest] = i;
            assign[i] = jbest;
            if (prev >= 0 && prev != i) {
                assign[prev] = -1;
                free_rows[sp++] = prev;
            }
            if (++total > limit) {
                for (int r = 0; r < n; ++r) rowsol[r] = assign[r];
                delete pool;
                return -total;
            }
        }
        if (eps <= eps_target * 1.0000001) break;
        double next = eps * 0.1;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
    for (int r = 0; r < n; ++r) rowsol[r] = assign[r];
    delete pool;
    return total;
}
