// Jonker-Volgenant LAPMOD-style dense solver.
// Column reduction + reduction transfer + shortest augmenting paths with
// a "todo" index set so each Dijkstra step scans only unlabeled columns,
// and columns are removed as they are scanned (O(n^2) total per augmentation
// worst case, but with good reduction the inner loops are shorter).
//
// This follows the structure of lap.cpp by Jonker (1987) / SciPy's rectangular_lsap
// but written for square double costs and compiled with -ffast-math -march=native.
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <cstring>

extern "C" int lapjv_fast(const double* cost, int n, int* rowsol) {
    const double INF = 1e18;
    std::vector<double> v(n), u(n, 0.0), d(n);
    std::vector<int> y(n, -1), x(n, -1), pred(n), free_rows;
    std::vector<int> col_list(n);
    std::vector<char> unique(n, 1);

    // ---- COLUMN REDUCTION ----
    // For each column find the minimum cost and the row achieving it (last one wins).
    std::fill(v.begin(), v.end(), INF);
    std::vector<int> col_min_row(n, 0);
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            if (row[j] < v[j]) { v[j] = row[j]; col_min_row[j] = i; }
        }
    }

    // Reverse scan for row reduction and initial assignment (Jonker)
    std::vector<char> col_taken(n, 0);
    free_rows.reserve(n);
    for (int i = n - 1; i >= 0; --i) {
        const double* row = cost + (size_t)i * n;
        double h = INF;
        int j1 = 0;
        double h2 = INF;
        for (int j = 0; j < n; ++j) {
            double red = row[j] - v[j];
            if (red < h) { h2 = h; h = red; j1 = j; }
            else if (red < h2) h2 = red;
        }
        u[i] = h;
        if (!col_taken[j1]) {
            col_taken[j1] = 1;
            x[i] = j1;
            y[j1] = i;
            // reduction transfer
            v[j1] -= (h2 - h);
        } else {
            free_rows.push_back(i);
        }
    }
    // free_rows currently high-to-low because we scanned i descending and pushed frees.
    // Process low index first (reverse).
    std::reverse(free_rows.begin(), free_rows.end());

    // Augmenting path with duals. Use an active list of unlabeled columns.
    std::vector<int> active(n);
    std::vector<int> active_pos(n);

    for (int fi = 0; fi < (int)free_rows.size(); ++fi) {
        int f = free_rows[fi];
        const double* frow = cost + (size_t)f * n;
        int na = n;
        for (int j = 0; j < n; ++j) {
            active[j] = j;
            active_pos[j] = j;
            d[j] = frow[j] - v[j];
            pred[j] = f;
        }
        int endj = -1;
        double mind = 0;
        // scanned columns stored implicitly by removal from active
        // We also need scanned set for dual update: record them.
        std::vector<int> scanned;
        scanned.reserve(64);
        while (na > 0) {
            // find min d among active
            int amin = 0;
            double md = d[active[0]];
            for (int t = 1; t < na; ++t) {
                double dj = d[active[t]];
                if (dj < md) { md = dj; amin = t; }
            }
            int jmin = active[amin];
            mind = md;
            // remove jmin from active (swap with last)
            int last = active[--na];
            active[amin] = last;
            active_pos[last] = amin;
            scanned.push_back(jmin);
            if (y[jmin] < 0) { endj = jmin; break; }
            int i2 = y[jmin];
            int jm = x[i2];
            const double* row = cost + (size_t)i2 * n;
            double cred = row[jm] - v[jm];
            // relax only active columns
            for (int t = 0; t < na; ++t) {
                int j = active[t];
                double nd = mind + row[j] - v[j] - cred;
                if (nd < d[j]) { d[j] = nd; pred[j] = i2; }
            }
        }
        if (endj < 0) {
            for (int i = 0; i < n; ++i) rowsol[i] = x[i];
            return -1;
        }
        // dual update on scanned columns
        u[f] = mind;
        for (int j : scanned) {
            double diff = mind - d[j];
            if (j != endj && y[j] >= 0) u[y[j]] += diff;
            v[j] -= diff;
        }
        // augment
        int j = endj;
        while (true) {
            int i = pred[j];
            int pj = x[i];
            x[i] = j;
            y[j] = i;
            if (i == f) break;
            j = pj;
        }
    }
    for (int i = 0; i < n; ++i) rowsol[i] = x[i];
    return (int)free_rows.size();
}
ENDCPP
