// Parallel Gauss-Seidel auction.
// Rows are partitioned across threads. Each thread runs an auction on its rows
// against ALL columns, using a private price vector initialized from the shared one.
// After the round, winning bids are merged (highest increment per column) into the
// shared price, losers are retried. This is a parallel Jacobi-over-blocks variant
// that does much more useful work per synchronization than a per-bid barrier.
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <cstring>
#include <thread>
#include <immintrin.h>

struct Bid { double inc; int i, j; };

static void best2(const double* row, const double* price, int n, double& best, double& second, int& jbest) {
    best = 1e300; second = 1e300; jbest = 0;
    int j = 0;
    for (; j + 8 <= n; j += 8) {
        __m256d r0 = _mm256_add_pd(_mm256_loadu_pd(row + j), _mm256_loadu_pd(price + j));
        __m256d r1 = _mm256_add_pd(_mm256_loadu_pd(row + j + 4), _mm256_loadu_pd(price + j + 4));
        alignas(32) double tmp[8];
        _mm256_store_pd(tmp, r0);
        _mm256_store_pd(tmp + 4, r1);
        for (int k = 0; k < 8; ++k) {
            double v = tmp[k];
            if (v < best) { second = best; best = v; jbest = j + k; }
            else if (v < second) second = v;
        }
    }
    for (; j < n; ++j) {
        double v = row[j] + price[j];
        if (v < best) { second = best; best = v; jbest = j; }
        else if (v < second) second = v;
    }
}

// Each thread solves a Gauss-Seidel auction for its subset of rows, treating columns
// as globally contended. Private prices start at shared prices. The thread assigns
// its rows; the price increases are proposals.
struct ThreadOut {
    std::vector<int> assign;      // local row -> col, or -1
    std::vector<double> price;    // private price after local auction
};

extern "C" int auction_parallel(const double* M, int n, int* rowsol, double eps_target, int nthreads) {
    if (nthreads < 1) nthreads = 1;
    if (nthreads > n) nthreads = n;

    std::vector<double> price(n, 0.0);
    for (int j = 0; j < n; ++j) {
        double m = M[j];
        for (int i = 1; i < n; ++i) {
            double v = M[(size_t)i * n + j];
            if (v < m) m = v;
        }
        price[j] = -m;
    }

    double maxc = 0;
    for (size_t k = 0, K = (size_t)n * n; k < K; ++k) if (M[k] > maxc) maxc = M[k];
    double eps = maxc * 0.05;
    if (eps < eps_target) eps = eps_target;

    // row partitions
    std::vector<int> bounds(nthreads + 1);
    for (int t = 0; t <= nthreads; ++t) bounds[t] = (int)((long long)t * n / nthreads);

    std::vector<int> owner(n, -1), assign(n, -1);

    auto run_phase = [&](double eps_now) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        std::vector<int> free_rows(n);
        int nfree = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        int guard = 0;
        while (nfree > 0 && guard < n * 30) {
            // Split free rows across threads. Each thread does a FULL local GS auction
            // on its free rows with a private price copy, producing proposals.
            int nth = nthreads;
            if (nfree < nthreads * 8) nth = 1;
            std::vector<std::vector<int>> local_free(nth);
            for (int t = 0; t < nfree; ++t) local_free[t % nth].push_back(free_rows[t]);

            struct Prop { int i, j; double new_price; };
            std::vector<std::vector<Prop>> props(nth);

            auto work = [&](int tid) {
                const auto& rows = local_free[tid];
                if (rows.empty()) return;
                std::vector<double> p = price; // private copy
                std::vector<int> local_owner(n, -1);
                std::vector<int> local_assign(n, -1);
                std::vector<int> st = rows;
                int sp = (int)st.size();
                int spins = 0;
                int limit = (int)rows.size() * n;
                while (sp > 0 && spins < limit) {
                    int i = st[--sp];
                    const double* row = M + (size_t)i * n;
                    double best, second; int jbest;
                    best2(row, p.data(), n, best, second, jbest);
                    p[jbest] += (second - best) + eps_now;
                    int prev = local_owner[jbest];
                    local_owner[jbest] = i;
                    local_assign[i] = jbest;
                    if (prev >= 0 && prev != i) {
                        local_assign[prev] = -1;
                        st[sp++] = prev;
                    }
                    ++spins;
