            else {
                std::vector<std::thread> th;
                for (int t = 0; t < nth; ++t) th.emplace_back(work, t);
                for (auto& t : th) t.join();
            }

            // Merge proposals: for each column, the highest new_price wins.
            std::vector<int> win_i(n, -1);
            std::vector<double> win_p(n, -1e300);
            for (int t = 0; t < nth; ++t) {
