                int prev = owner[j];
                owner[j] = i;
                assign[i] = j;
                got[i] = 1;
                if (prev >= 0 && prev != i) { assign[prev] = -1; newly.push_back(prev); }
            }
            for (int t = 0; t < nfree; ++t) if (!got[free_rows[t]]) newly.push_back(free_rows[t]);
            // unique newly
            std::sort(newly.begin(), newly.end());
            newly.erase(std::unique(newly.begin(), newly.end()), newly.end());
            nfree = (int)newly.size();
            if (nfree) std::memcpy(free_rows.data(), newly.data(), sizeof(int) * nfree);
            ++guard;
            if (nth == 1 && nfree == 0) break;
        }
        return nfree == 0;
    };

    while (true) {
