// Cost-scaling for the dense assignment problem (unit-capacity bipartite min-cost flow).
// Goldberg-Kennedy style refine:
//   eps starts large, halves each phase.
//   A node is active if it has excess. We push along eps-admissible edges
//   (reduced cost < eps) and relabel when none exist.
// For assignment, supplies are +1 at sources and -1 at targets (deficit).
// Potentials u[source], v[target]. Reduced cost of i->j is C[i,j] - u[i] - v[j].
// Admissible if reduced cost < eps (we use integer costs and eps integer).
//
// To avoid O(n) admissible search, each source keeps a cursor and we only scan
// when relabeling. Relabel sets u[i] = max_j (C[i,j] - v[j]) - eps, i.e. the
// largest u such that some edge is admissible? For minimization push-relabel:
//   admissible if rc < 0 after scaling... I'll use the auction-equivalent
//   cost-scaling described by Bertsekas/Castanon which is essentially auction.
//
// IMPLEMENTATION: integer cost scaling successive shortest paths with a DIAL bucket
// queue is awkward for large cost range. Instead use cost scaling where each
// refine doubles precision and warm-starts duals, and the number of augmentations
// per scale is small because the previous matching is nearly optimal.
//
// Practical algorithm (scaling successive shortest paths):
//   for scale from coarse to fine:
//     costs are rounded to current scale
//     current matching + duals are eps-optimal for previous scale
//     run auction/SSP only to fix violations, warm-started
// This is what auction epsilon-scaling already does. The missing speed is the scan.
//
// NEW IDEA: blocked column pruning. Maintain for each row the best reduced cost
// seen and a threshold. Skip columns whose price is so high they cannot improve
// the current best. Prices only increase, so a column that is too expensive stays
// too expensive until the row is displaced and its best rises.
// During a single row scan we still must look at all columns the first time.
// Subsequent bids of the SAME row can skip columns with price[j] >= second_best - M_min_row.
// When a row is displaced and bids again, prices have only increased, so the skip set grows.
//
// bound: a column j cannot be the best if M[i,j] + price[j] >= current_second_threshold.
// We don't know second until we scan. Partial scan: process columns in order of
// increasing price (prices change, so order is stale).
//
// Maintain columns in a tournament of prices? Finding the min of M[i,j]+price[j]
// is a classic problem. With price updates (point updates) and many row vectors,
// a block-min structure helps:
//   Partition columns into blocks of B=16. Store block_min_price[block].
//   Lower bound of reduced cost in a block for row i is min_M_in_block[i,block] + block_min_price.
//   We can skip blocks whose lower bound exceeds the current second-best.
//   min_M_in_block is n * (n/B) precomputed — for B=16, 600*38 = 22k doubles, cheap.
//   First scan still touches most blocks, but later scans skip.
//
// Let's measure how many blocks survive after prices develop.

#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <cstring>
#include <immintrin.h>

extern "C" int auction_blocked(const double* M, int n, int* rowsol, double eps_target, int B) {
    int nblocks = (n + B - 1) / B;
    std::vector<double> block_minM((size_t)n * nblocks);
    for (int i = 0; i < n; ++i) {
        const double* row = M + (size_t)i * n;
        for (int b = 0; b < nblocks; ++b) {
            int lo = b * B, hi = std::min(n, lo + B);
            double m = row[lo];
            for (int j = lo + 1; j < hi; ++j) if (row[j] < m) m = row[j];
            block_minM[(size_t)i * nblocks + b] = m;
        }
    }
    std::vector<double> price(n, 0.0);
    std::vector<double> block_minP(nblocks, 0.0);
    auto recompute_block_prices = [&]() {
        for (int b = 0; b < nblocks; ++b) {
            int lo = b * B, hi = std::min(n, lo + B);
            double m = price[lo];
            for (int j = lo + 1; j < hi; ++j) if (price[j] < m) m = price[j];
            block_minP[b] = m;
        }
    };
    // init price = -colmin, then block prices
    for (int j = 0; j < n; ++j) {
        double m = M[j];
        for (int i = 1; i < n; ++i) {
            double v = M[(size_t)i * n + j];
            if (v < m) m = v;
        }
        price[j] = -m;
    }
    recompute_block_prices();

    std::vector<int> owner(n, -1), assign(n, -1), free_rows(n);
    double maxc = 0;
    for (size_t k = 0, K = (size_t)n * n; k < K; ++k) if (M[k] > maxc) maxc = M[k];
    double eps = maxc * 0.05;
    if (eps < eps_target) eps = eps_target;

    long long scanned_cols = 0, scanned_blocks = 0, skipped_blocks = 0;
    int total = 0;
    const int limit = n * n * 4;

    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int sp = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        while (sp > 0) {
            int i = free_rows[--sp];
            const double* row = M + (size_t)i * n;
            const double* bmin = block_minM.data() + (size_t)i * nblocks;
            double best = 1e300, second = 1e300;
            int jbest = 0;
            // first pass: find a threshold using block lower bounds — we still need exact best.
            // Scan blocks in order of lower bound (small nblocks=38, sort is cheap vs scan).
            // Actually evaluate promising blocks fully, skip blocks whose LB >= second once second is known.
            // Start by scanning the 4 blocks with smallest LB to seed best/second, then prune.
            // For simplicity and speed: linear block scan with pruning.
            for (int b = 0; b < nblocks; ++b) {
                double lb = bmin[b] + block_minP[b];
                if (lb >= second) { ++skipped_blocks; continue; }
                ++scanned_blocks;
                int lo = b * B, hi = std::min(n, lo + B);
                for (int j = lo; j < hi; ++j) {
                    double v = row[j] + price[j];
                    ++scanned_cols;
                    if (v < best) { second = best; best = v; jbest = j; }
                    else if (v < second) second = v;
                }
            }
            int jold_block = jbest / B;
            price[jbest] += (second - best) + eps;
            // update block min price (may only increase)
            {
                int lo = jold_block * B, hi = std::min(n, lo + B);
                double m = price[lo];
                for (int j = lo + 1; j < hi; ++j) if (price[j] < m) m = price[j];
                block_minP[jold_block] = m;
            }
            int prev = owner[jbest];
            owner[jbest] = i;
            assign[i] = jbest;
            if (prev >= 0 && prev != i) {
                assign[prev] = -1;
                free_rows[sp++] = prev;
            }
            if (++total > limit) {
                for (int r = 0; r < n; ++r) rowsol[r] = assign[r];
                return -total;
            }
        }
        if (eps <= eps_target * 1.0000001) break;
        double next = eps * 0.1;
        if (next < eps_target) next = eps_target;
        eps = next;
    }
    for (int r = 0; r < n; ++r) rowsol[r] = assign[r];
    // stash stats in rowsol? no, print via a side channel: store in a global
    static long long g_scanned = 0, g_skip = 0, g_blocks = 0;
    g_scanned = scanned_cols; g_skip = skipped_blocks; g_blocks = scanned_blocks;
    return total;
}

// export stats
static long long stat_scanned = 0;
ENDCPP
