struct Bid { double best, second; int j; };

static inline void best2(const double* row, const double* price, int n, Bid& b) {
    double best = 1e300, second = 1e300;
    int jbest = 0;
    int j = 0;
    for (; j + 8 <= n; j += 8) {
        __m256d r0 = _mm256_add_pd(_mm256_loadu_pd(row + j), _mm256_loadu_pd(price + j));
        __m256d r1 = _mm256_add_pd(_mm256_loadu_pd(row + j + 4), _mm256_loadu_pd(price + j + 4));
        alignas(32) double t[8];
        _mm256_store_pd(t, r0);
        _mm256_store_pd(t + 4, r1);
        for (int k = 0; k < 8; ++k) {
            double v = t[k];
            if (v < best) { second = best; best = v; jbest = j + k; }
            else if (v < second) second = v;
        }
    }
    for (; j < n; ++j) {
        double v = row[j] + price[j];
        if (v < best) { second = best; best = v; jbest = j; }
        else if (v < second) second = v;
    }
    b.best = best; b.second = second; b.j = jbest;
}

extern "C" int jacobi(const double* M, int n, int* rowsol, double eps_target) {
    std::vector<double> price(n);
