    std::vector<int> owner(n, -1), assign(n, -1), free_rows(n), next_free(n);
    std::vector<Bid> bids(n);
    std::vector<int> win_i(n);
    std::vector<double> win_inc(n);
    std::vector<char> got(n);

    int rounds = 0;
    while (true) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nfree = n;
        for (int i = 0; i < n; ++i) free_rows[i] = i;
        int guard = 0;
