                best2(M + (size_t)i * n, price.data(), n, bids[i]);
            }
            std::fill(win_i.begin(), win_i.end(), -1);
            std::fill(win_inc.begin(), win_inc.end(), -1.0);
            for (int t = 0; t < nfree; ++t) {
                int i = free_rows[t];
                int j = bids[i].j;
                double inc = (bids[i].second - bids[i].best) + eps;
                if (inc > win_inc[j]) { win_inc[j] = inc; win_i[j] = i; }
            }
            std::fill(got.begin(), got.end(), 0);
            int nnext = 0;
            for (int j = 0; j < n; ++j) {
                int i = win_i[j];
                if (i < 0) continue;
                price[j] += win_inc[j];
                int prev = owner[j];
                owner[j] = i;
                assign[i] = j;
                got[i] = 1;
